insert into public.exercise_templates (slug, title, description, kind, approach, audience, collection, estimated_minutes, sort_order, steps) values
  ('cuadro-panico-act-aceptacion', 'Pánico: dejar de pelear con las sensaciones', 'Una mirada desde ACT: hacerles lugar a las sensaciones de ansiedad en vez de luchar contra ellas, y practicar observarlas.', 'custom', 'act', 'todos', 'cuadros', 12, 330,
   $steps$[ { "id": "intro", "type": "info", "title": "Cuando pelear no ayuda", "content": "Cuando aparecen las sensaciones del pánico, lo más natural es querer frenarlas: controlar la respiración, escaparse, distraerse a toda costa.\n\nEl problema es que, muchas veces, **esa pelea termina alimentando la alarma**. Cuanto más empujamos para que la sensación se vaya, más atención le ponemos y más amenazante parece.\n\nEste ejercicio propone otra cosa, desde la Terapia de Aceptación y Compromiso (ACT): **hacerles lugar a las sensaciones**, sin que te gusten, para que dejen de manejar tu vida. Hacelo en un momento tranquilo." }, { "id": "seguridad", "type": "info", "title": "Antes de empezar", "content": "Si tenés síntomas nuevos, dolor de pecho intenso o distinto de lo habitual, o pensás en hacerte daño, **pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nSi nunca te hicieron un control médico por estos síntomas, conviene consultarlo con tu médico/a.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "estrategias", "type": "checklist", "prompt": "¿Qué hacés habitualmente para sacarte de encima las sensaciones? Marcá las que reconozcas.", "options": [ "Irme del lugar", "Evitar ciertos lugares o actividades", "Controlarme el pulso o la respiración", "Distraerme con el celular", "Pedir que alguien me acompañe", "Llevar algo «por las dudas» (agua, pastillas)", "Pelear mentalmente con la sensación", "Otra cosa" ], "min": 1 }, { "id": "costo", "type": "text", "prompt": "A la larga, ¿qué te cuestan esas estrategias? ¿Qué dejaste de hacer por la ansiedad?", "placeholder": "Por ejemplo: dejé de ir al súper solo/a, ya no viajo en colectivo" }, { "id": "metafora", "type": "info", "title": "El tira y afloje con el monstruo", "content": "Imaginá que estás en un tira y afloje con un monstruo, la ansiedad. Entre ustedes hay un pozo. Tirás con todas tus fuerzas, y el monstruo tira más fuerte. Cuanto más tirás, más cansado/a estás y más cerca del pozo quedás.\n\n¿Qué pasaría si **soltaras la soga**?\n\nEl monstruo no desaparece: sigue ahí, haciendo ruido. Pero tus manos quedan libres para hacer otras cosas que te importan.\n\nSoltar la soga no es rendirse ni resignarse. Es **dejar de gastar energía en una pelea que no se puede ganar**, y usarla en tu vida." }, { "id": "disposicion_quiz", "type": "choice", "prompt": "En ACT, ¿qué significa estar «dispuesto/a» a sentir ansiedad?", "options": [ "Que me tiene que gustar sentirla", "Hacerle lugar mientras hago lo que me importa", "Aguantar apretando los dientes hasta que pase" ], "feedback": { "Que me tiene que gustar sentirla": "No hace falta que te guste. Podés no querer sentirla y, aun así, hacerle lugar.", "Hacerle lugar mientras hago lo que me importa": "Exacto. Disposición es abrirte a la sensación, sin pelearla, para que no decida por vos.", "Aguantar apretando los dientes hasta que pase": "Aguantar tenso/a sigue siendo una forma de pelea. La disposición es más bien aflojar y dejar que esté." } }, { "id": "defusion", "type": "info", "title": "«Me va a pasar algo»", "content": "En una crisis, la mente suele gritar: «me va a pasar algo», «me voy a morir», «me voy a volver loco/a». Son pensamientos, no hechos, aunque se sientan muy reales.\n\nUna forma de tomar distancia es **ponerle un prefijo**:\n\n- En vez de «me va a pasar algo», notá: **«estoy teniendo el pensamiento de que me va a pasar algo»**.\n- O agradecele a tu mente: **«gracias, mente, por intentar cuidarme»**.\n\nNo se trata de discutir con el pensamiento ni de convencerte de que es falso, sino de verlo como lo que es: palabras que tu mente produce cuando suena la alarma." }, { "id": "pensamiento", "type": "text", "prompt": "¿Qué frase suele decirte tu mente en una crisis? Escribila con el prefijo «Estoy teniendo el pensamiento de que…».", "placeholder": "Estoy teniendo el pensamiento de que…" }, { "id": "observar", "type": "timed_info", "title": "Observar las sensaciones", "content": "Sentate cómodo/a y cerrá los ojos si querés.\n\n- **Notá tu cuerpo** como si fuera la primera vez: el ritmo del corazón, el aire que entra y sale, cualquier tensión.\n- Si encontrás una sensación incómoda, **describila con curiosidad**: ¿dónde está?, ¿tiene borde?, ¿es caliente, fría, punzante?\n- **Respirá hacia ella**, como haciéndole espacio, sin intentar que se vaya.\n- Si aparecen pensamientos, notalos («ahí está la mente») y volvé al cuerpo.\n\nNo hace falta que te sientas bien. Solo practicás estar con lo que hay.", "seconds": 120 }, { "id": "notaste", "type": "text", "prompt": "¿Qué notaste mientras observabas? ¿Cambió algo en la sensación o en tu forma de mirarla?", "placeholder": "Lo que noté" }, { "id": "importa", "type": "text", "prompt": "Si la ansiedad no decidiera por vos, ¿qué cosa te gustaría hacer, aunque las sensaciones vinieran?", "placeholder": "Por ejemplo: volver a ir al cine con mi hermana" }, { "id": "paso", "type": "text", "prompt": "¿Qué paso chico podrías dar hacia eso esta semana, haciéndole lugar a la ansiedad?", "placeholder": "Por ejemplo: ir al súper diez minutos, aunque me acelere" }, { "id": "resumen", "type": "reflect", "title": "Soltar la soga", "template": "Lo que suelo hacer para pelear con la ansiedad: {{estrategias}}. Lo que me cuesta: {{costo}}. Mi pensamiento, con distancia: {{pensamiento}}. Lo que quiero hacer: {{importa}}. Mi paso de esta semana: {{paso}}.", "content": "Si el paso que elegiste te parece mucho, achicalo. Llevá esto a la próxima sesión para seguir planificando con tu psicólogo/a." } ]$steps$::jsonb),
  ('cuadro-panico-dbt-crisis', 'Mi kit para un pico de ansiedad', 'Habilidades de DBT para atravesar un pico de ansiedad sin empeorar las cosas: STOP, respiración pausada, cinco sentidos y distracción.', 'custom', 'dbt', 'todos', 'cuadros', 13, 331,
   $steps$[ { "id": "intro", "type": "info", "title": "Sobrevivir al pico", "content": "Hay momentos en que la ansiedad sube tanto que cuesta pensar. En la Terapia Dialéctica Conductual (DBT) existen las **habilidades de supervivencia a la crisis**: herramientas para atravesar ese pico **sin hacer algo que empeore las cosas**.\n\nNo resuelven el problema de fondo ni hacen desaparecer la ansiedad: ayudan a que el momento pase con menos daño.\n\nEn este ejercicio vas a conocer algunas y a **armar tu propio kit**, para tenerlo a mano. Conviene practicarlas cuando estás tranquilo/a, así después salen más fácil." }, { "id": "seguridad", "type": "info", "title": "Si necesitás ayuda urgente", "content": "Si estás en una crisis que no podés manejar, tenés síntomas nuevos o dolor de pecho intenso, o pensás en hacerte daño, **pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "senales", "type": "checklist", "prompt": "¿Qué señales te avisan que la ansiedad está subiendo fuerte? Marcá las tuyas.", "options": [ "Corazón acelerado", "Respiración corta", "Ganas de salir corriendo", "Pensamientos que se aceleran", "Tensión en el cuerpo", "Irritabilidad", "Sensación de irrealidad", "Ganas de llorar" ], "min": 1 }, { "id": "stop", "type": "info", "title": "STOP", "content": "Cuando notás que la ansiedad se dispara, probá **STOP**:\n\n- **S – Stop (pará):** frená un segundo. No hagas nada todavía.\n- **T – Tomá distancia:** da un paso atrás, físico o mental. Respirá.\n- **O – Observá:** ¿qué pasa en tu cuerpo, qué pensás, qué está pasando alrededor?\n- **P – Procedé con conciencia:** elegí qué hacer pensando en lo que te sirve, no solo en escapar de la sensación.\n\nSTOP lleva unos segundos y te da margen para elegir." }, { "id": "respiracion", "type": "timed_info", "title": "Respiración pausada", "content": "Vamos a practicar una respiración en la que la exhalación es más larga que la inhalación. Eso le avisa al cuerpo que puede bajar un cambio.\n\n- **Inhalá por la nariz** contando hasta 4.\n- **Exhalá lento** contando hasta 6 u 8, como si soplaras por una pajita.\n\nSin forzar ni llenar del todo los pulmones. Si te mareás, volvé a respirar normal.", "seconds": 90 }, { "id": "sentidos_info", "type": "info", "title": "Autocalmarme con los cinco sentidos", "content": "Otra habilidad es **darte algo amable por cada sentido**, como harías con alguien querido que está pasándola mal:\n\n- **Vista:** una foto que te guste, mirar el cielo o las plantas.\n- **Oído:** una canción tranquila, un audio que te calme.\n- **Olfato:** un perfume, café, una crema con aroma.\n- **Gusto:** un caramelo, un mate o un té tibio, tomado despacio.\n- **Tacto:** una manta, una ducha tibia, acariciar a una mascota.\n\nLo ideal es tener algunas de estas cosas a mano antes de que las necesites." }, { "id": "sentidos", "type": "list", "prompt": "Elegí una cosa concreta para cada sentido que te sirva para calmarte (vista, oído, olfato, gusto, tacto).", "count": 5, "min": 3 }, { "id": "accepts_info", "type": "info", "title": "Distraerme a propósito: ACCEPTS", "content": "Cuando la ansiedad está muy alta, a veces sirve **cambiar el foco por un rato**. En DBT se resume en ACCEPTS:\n\n- **Actividades:** ordenar, cocinar, caminar.\n- **Contribuir:** ayudar a alguien, mandar un mensaje lindo.\n- **Comparar:** recordar otras veces en que lo atravesaste.\n- **Emociones opuestas:** un video gracioso, música alegre.\n- **Pausar (dejar de lado):** «esto lo pienso después».\n- **Pensamientos:** contar de 100 para atrás de a 7, armar una lista mental.\n- **Sensaciones:** apretar una pelotita, un hielo en la mano.\n\nNo es evitar para siempre: es ganar tiempo hasta que el pico baje." }, { "id": "accepts", "type": "checklist", "prompt": "¿Cuáles de estas formas de distraerte podrías usar vos? Marcá las que te parezcan útiles.", "options": [ "Actividades", "Contribuir", "Comparar", "Emociones opuestas", "Pausar", "Pensamientos", "Sensaciones" ], "min": 1 }, { "id": "accepts_concreto", "type": "text", "prompt": "Escribí una o dos actividades concretas de las que marcaste.", "placeholder": "Por ejemplo: salir a caminar a la cuadra, contar de 100 para atrás de a 7" }, { "id": "evitar", "type": "text", "prompt": "¿Qué cosas suelen empeorar el momento y querés evitar? (cafeína, discutir, buscar síntomas en internet…)", "placeholder": "Lo que no me ayuda" }, { "id": "persona", "type": "text", "prompt": "¿A quién podrías escribirle o llamar si el pico no baja?", "placeholder": "Nombre de una o dos personas" }, { "id": "resumen", "type": "reflect", "title": "Mi kit para un pico de ansiedad", "template": "Mis señales: {{senales}}. Primero: STOP y respiración pausada. Para calmarme con los sentidos: {{sentidos}}. Para distraerme: {{accepts_concreto}}. Lo que evito: {{evitar}}. A quién recurro: {{persona}}.", "content": "Sacale una captura o anotalo en el celular para tenerlo a mano. Estas habilidades no reemplazan el trabajo en sesión: contale a tu psicólogo/a cómo te fue al usarlas." } ]$steps$::jsonb),
  ('cuadro-depresion-act-valores', 'Mis valores y un paso chico', 'Un ejercicio de ACT para reconectar con lo que te importa en distintas áreas de tu vida y elegir una acción chica para esta semana.', 'custom', 'act', 'todos', 'cuadros', 14, 332,
   $steps$[ { "id": "intro", "type": "info", "title": "Cuando todo cuesta", "content": "Cuando el ánimo está bajo, es común perder las ganas y sentir que nada tiene sentido. Muchas veces esperamos **tener ganas para hacer**, pero con el ánimo bajo las ganas tardan en llegar.\n\nDesde la Terapia de Aceptación y Compromiso (ACT) se propone otro camino: **orientarte por tus valores**, es decir, por lo que te importa, y dar pasos chicos en esa dirección, aunque las ganas no estén del todo.\n\nNo es «pensar en positivo» ni obligarte a estar bien. Es ir recuperando, de a poco, cosas que tienen sentido para vos." }, { "id": "seguridad", "type": "info", "title": "Si necesitás ayuda urgente", "content": "Si en algún momento sentís que no podés más, pensás en hacerte daño o en no seguir viviendo, **pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano. También podés avisarle a alguien de confianza.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "valores_info", "type": "info", "title": "Qué son los valores", "content": "Los valores son **direcciones**, no metas. Una meta se cumple y se tacha («terminar un curso»). Un valor es una forma de vivir que podés seguir eligiendo siempre («seguir aprendiendo»).\n\nAlgunos ejemplos: ser una persona presente con tu familia, cuidar tu cuerpo, ser honesto/a, aportar a otros, disfrutar de la naturaleza, crear cosas.\n\nLos valores no tienen que justificarse ni ser los «correctos»: **son tuyos**. Y siguen ahí aunque hoy te cueste ir hacia ellos." }, { "id": "areas", "type": "checklist", "prompt": "¿Qué áreas de tu vida te importan más en este momento? Elegí hasta tres.", "options": [ "Familia", "Pareja", "Amistades", "Trabajo o estudio", "Salud y cuerpo", "Tiempo libre y disfrute", "Crecimiento personal", "Comunidad o espiritualidad" ], "min": 1, "max": 3 }, { "id": "valor", "type": "text", "prompt": "En una de esas áreas, ¿qué tipo de persona te gustaría ser? ¿Qué querés que se note de vos?", "placeholder": "Por ejemplo: en mis amistades, quiero ser alguien que está presente" }, { "id": "diana_info", "type": "info", "title": "La diana de valores", "content": "Imaginá una diana de tiro al blanco. El centro es **vivir plenamente de acuerdo con ese valor**. Los bordes, estar muy lejos de él.\n\nNo se trata de juzgarte por dónde estás. Con el ánimo bajo, es esperable alejarse un poco de lo que nos importa. La idea es **ver con honestidad y sin castigarte** dónde estás hoy, para saber hacia dónde mover el próximo paso." }, { "id": "diana", "type": "scale", "prompt": "Hoy, ¿qué tan cerca sentís que estás de vivir de acuerdo con ese valor?", "min": 0, "max": 10, "min_label": "Muy lejos", "max_label": "En el centro" }, { "id": "accion", "type": "text", "prompt": "¿Qué acción chica y concreta podrías hacer esta semana en esa dirección?", "placeholder": "Por ejemplo: mandarle un mensaje a una amiga el jueves" }, { "id": "accion_quiz", "type": "choice", "prompt": "¿Cuál de estas acciones es más fácil de llevar a cabo?", "options": [ "Ser mejor amigo/a", "Llamar a Laura el sábado a la tarde", "Cambiar mi vida social" ], "feedback": { "Ser mejor amigo/a": "Eso se parece más a un valor. Para la acción conviene algo concreto: qué, con quién y cuándo.", "Llamar a Laura el sábado a la tarde": "Sí. Es chica, concreta y tiene día. Así es más probable que pase, aunque las ganas no acompañen.", "Cambiar mi vida social": "Es una meta grande y difusa. Probá achicarla hasta algo que puedas hacer en un rato." } }, { "id": "cuando", "type": "text", "prompt": "¿Cuándo y dónde la vas a hacer?", "placeholder": "Día, hora o momento del día" }, { "id": "barreras", "type": "checklist", "prompt": "¿Qué podría aparecer en el camino? Marcá lo que te parezca probable.", "options": [ "Cansancio", "Falta de ganas", "Pensamientos como «no sirve de nada»", "Vergüenza o miedo", "Falta de tiempo", "Otra cosa" ], "min": 1 }, { "id": "disposicion", "type": "text", "prompt": "Si aparecen esas barreras, ¿qué te gustaría decirte o hacer para dar el paso igual, aunque sea más chico?", "placeholder": "Por ejemplo: «puedo hacerlo cansado/a; con cinco minutos alcanza»" }, { "id": "resumen", "type": "reflect", "title": "Mi paso de esta semana", "template": "Áreas que me importan: {{areas}}. Mi valor: {{valor}}. Mi acción: {{accion}}. Cuándo: {{cuando}}. Lo que puede aparecer: {{barreras}}. Lo que me voy a decir: {{disposicion}}.", "content": "Si no sale como planeaste, no es un fracaso: es información para ajustar el paso. Contáselo a tu psicólogo/a en la próxima sesión." } ]$steps$::jsonb),
  ('cuadro-depresion-dbt-positivos', 'Sumar momentos buenos y cuidar el cuerpo', 'Habilidades de DBT para el ánimo bajo: acumular emociones positivas y cuidar el cuerpo (PLEASE), con un plan para la semana.', 'custom', 'dbt', 'todos', 'cuadros', 14, 333,
   $steps$[ { "id": "intro", "type": "info", "title": "Llenar el tanque", "content": "Cuando el ánimo está bajo, solemos dejar de hacer justamente las cosas que nos hacen bien. Y cuanto menos hacemos, más baja el ánimo.\n\nLa Terapia Dialéctica Conductual (DBT) propone dos habilidades para cortar ese círculo:\n\n- **Acumular emociones positivas:** sumar, a propósito, momentos agradables y cosas con sentido.\n- **PLEASE:** cuidar el cuerpo, porque un cuerpo agotado hace a las emociones más difíciles.\n\nNo se trata de obligarte a estar contento/a. Se trata de **darle al ánimo mejores condiciones**, de a poco." }, { "id": "seguridad", "type": "info", "title": "Si necesitás ayuda urgente", "content": "Si en algún momento sentís que no podés más, pensás en hacerte daño o en no seguir viviendo, **pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano. También podés avisarle a alguien de confianza.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "animo", "type": "scale", "prompt": "¿Cómo está tu ánimo hoy?", "min": 0, "max": 10, "min_label": "Muy bajo", "max_label": "Muy bien", "maps_to": "emotion_before" }, { "id": "corto_info", "type": "info", "title": "A corto plazo: momentos agradables", "content": "La idea es **hacer al menos una cosa agradable por día**, aunque sea chiquita, y estar presente mientras la hacés.\n\nAlgunos ejemplos: tomar un mate al sol, escuchar un tema que te guste, bañarte sin apuro, mirar una serie liviana, cocinar algo rico, salir a caminar, charlar con alguien.\n\nUn detalle importante: si la mente se va a «esto no me sirve» o «no me lo merezco», **notalo y volvé a lo que estás haciendo**. No hace falta disfrutar al máximo; alcanza con dejar que el momento esté." }, { "id": "agradables", "type": "list", "prompt": "Escribí cuatro cosas chicas y agradables que podrías hacer en tu día a día.", "count": 4, "min": 2 }, { "id": "largo", "type": "text", "prompt": "A largo plazo: ¿qué te gustaría ir construyendo, aunque sea de a poco? (un vínculo, un proyecto, un hábito)", "placeholder": "Por ejemplo: retomar la guitarra, volver a ver a mis amigos del club" }, { "id": "largo_paso", "type": "text", "prompt": "¿Cuál sería un primer paso chico hacia eso?", "placeholder": "Por ejemplo: sacar la guitarra del ropero y afinarla" }, { "id": "please_info", "type": "info", "title": "PLEASE: cuidar el cuerpo", "content": "PLEASE resume cuidados básicos que hacen a las emociones menos vulnerables:\n\n- **Salud física:** atender dolores o enfermedades y seguir las indicaciones médicas.\n- **Alimentación:** comer en horarios más o menos regulares, sin saltear comidas.\n- **Sustancias:** evitar o reducir alcohol y otras drogas, que empeoran el ánimo.\n- **Sueño:** horarios parecidos para acostarte y levantarte.\n- **Ejercicio:** moverte un poco cada día, a tu ritmo (caminar ya cuenta).\n\nSi tomás medicación, no la cambies por tu cuenta: cualquier ajuste se habla con quien te la indicó." }, { "id": "please", "type": "checklist", "prompt": "¿En qué área del cuerpo te gustaría poner más atención esta semana? Elegí una o dos.", "options": [ "Salud física", "Alimentación", "Sustancias", "Sueño", "Ejercicio o movimiento" ], "min": 1, "max": 2 }, { "id": "please_accion", "type": "text", "prompt": "¿Qué vas a hacer concretamente en esa área? Que sea chico y realista.", "placeholder": "Por ejemplo: acostarme antes de las 24 de lunes a jueves" }, { "id": "plan", "type": "text", "prompt": "Armá tu plan: ¿qué días vas a hacer tus actividades agradables y tu cuidado del cuerpo?", "placeholder": "Por ejemplo: lunes caminata, miércoles llamo a mi tía, todos los días mate al sol" }, { "id": "animo_despues", "type": "scale", "prompt": "Después de armar tu plan, ¿cómo está tu ánimo?", "min": 0, "max": 10, "min_label": "Muy bajo", "max_label": "Muy bien", "maps_to": "emotion_after" }, { "id": "resumen", "type": "reflect", "title": "Mi plan de la semana", "template": "Momentos agradables: {{agradables}}. Lo que quiero construir: {{largo}}, empezando por: {{largo_paso}}. Cuidado del cuerpo: {{please}} → {{please_accion}}. Mi plan: {{plan}}.", "content": "Es esperable que algunos días no salga. Lo importante es retomar, no hacerlo perfecto. Llevá este plan a la próxima sesión." } ]$steps$::jsonb),
  ('cuadro-toc-act-defusion', 'TOC: tomar distancia de las obsesiones', 'Prácticas de ACT para ver las obsesiones como pensamientos que pasan, sin discutirlas, sin rituales mentales y sin buscar certeza.', 'custom', 'act', 'todos', 'cuadros', 12, 334,
   $steps$[ { "id": "intro", "type": "info", "title": "Pensamientos pegajosos", "content": "En el TOC, algunos pensamientos se sienten **urgentes y peligrosos**, como si hubiera que hacer algo ya para neutralizarlos: revisar, repasar, rezar, buscar que alguien te asegure.\n\nDesde la Terapia de Aceptación y Compromiso (ACT) se trabaja la **defusión**: aprender a ver el pensamiento como un pensamiento, y no como una orden o una verdad.\n\nOjo: **el objetivo no es que la obsesión se vaya ni sentirte seguro/a**. Es poder dejarla estar, sin responderle, mientras seguís con lo que estabas haciendo." }, { "id": "seguridad", "type": "info", "title": "Si necesitás ayuda urgente", "content": "Si en algún momento estás en crisis, sentís que no podés más o pensás en hacerte daño, **pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "trampas", "type": "checklist", "prompt": "Cuando aparece la obsesión, ¿cuáles de estas cosas hacés para sacártela de encima? Marcá las que reconozcas.", "options": [ "Discutir mentalmente con el pensamiento", "Repasar recuerdos para estar seguro/a", "Rezar o repetir frases para neutralizar", "Buscar información en internet", "Preguntar a otros si está todo bien", "Intentar no pensar en eso", "Reemplazarlo por un pensamiento «bueno»" ], "min": 1 }, { "id": "trampa_info", "type": "info", "title": "La trampa de la certeza", "content": "Todo lo que marcaste tiene algo en común: **intenta conseguir certeza** de que no va a pasar nada malo. Da alivio un rato, pero le enseña al cerebro que la duda era peligrosa, y la obsesión vuelve con más fuerza.\n\nLos rituales mentales también son rituales, aunque nadie los vea.\n\nLa defusión propone algo distinto: **no contestarle a la obsesión**. Ni para darle la razón ni para discutirla. Solo notarla y dejarla estar, aunque la duda quede abierta." }, { "id": "obsesion", "type": "text", "prompt": "Escribí, en pocas palabras, una obsesión que te aparezca seguido. No hace falta detallarla.", "placeholder": "Por ejemplo: «¿y si dejé la puerta abierta?»" }, { "id": "prefijo", "type": "info", "title": "«Estoy teniendo el pensamiento de…»", "content": "Probá decir la obsesión en voz baja, tal como aparece. Después decila así:\n\n**«Estoy teniendo el pensamiento de que…»**\n\nY después:\n\n**«Me doy cuenta de que estoy teniendo el pensamiento de que…»**\n\nNotá si cambia algo, aunque sea un poco, la distancia entre vos y el pensamiento. No buscás que el pensamiento deje de molestar ni que se vuelva falso: buscás verlo **desde un poquito más lejos**." }, { "id": "historia", "type": "text", "prompt": "Si tu mente contara siempre la misma historia, ¿qué nombre le pondrías? Por ejemplo: «la historia del desastre».", "placeholder": "Ah, ahí está otra vez «la historia de…»" }, { "id": "hojas", "type": "timed_info", "title": "Hojas en el río", "content": "Sentate cómodo/a. Imaginá un arroyo que corre tranquilo, con hojas que flotan.\n\n- Cada vez que aparezca un pensamiento, una imagen o una duda, **ponela sobre una hoja** y mirá cómo se aleja con el agua.\n- Si aparece la obsesión, también va a una hoja. **No la empujes ni la retengas.**\n- Si te enganchás y empezás a analizarla, está bien: notalo, y volvé a poner el pensamiento sobre una hoja.\n- Si aparece la urgencia de revisar o de asegurarte, eso también puede ir a una hoja.\n\nNo hace falta que el río esté vacío. Solo practicás mirar.", "seconds": 150 }, { "id": "notaste", "type": "text", "prompt": "¿Qué notaste? ¿Hubo momentos en que te enganchaste con la obsesión? ¿Qué pasó cuando la dejaste pasar?", "placeholder": "Lo que noté" }, { "id": "quiz", "type": "choice", "prompt": "Aparece la duda «¿y si lastimé a alguien sin darme cuenta?». ¿Qué respuesta va más con la defusión?", "options": [ "Repasar el día para asegurarme de que no pasó", "«Estoy teniendo el pensamiento de que lastimé a alguien» y seguir", "Convencerme de que soy buena persona" ], "feedback": { "Repasar el día para asegurarme de que no pasó": "Eso es un ritual mental: busca certeza y alimenta el círculo, aunque alivie un rato.", "«Estoy teniendo el pensamiento de que lastimé a alguien» y seguir": "Sí. Notás el pensamiento, no le contestás y volvés a lo que estabas haciendo, aunque la duda siga ahí.", "Convencerme de que soy buena persona": "Suena lógico, pero también es una forma de neutralizar y buscar certeza. La defusión no discute el contenido." } }, { "id": "frase", "type": "text", "prompt": "Escribí una frase corta para usar cuando aparezca la obsesión, sin buscar certeza.", "placeholder": "Por ejemplo: «Ahí está la historia de la puerta. Puede quedarse; yo sigo.»" }, { "id": "resumen", "type": "reflect", "title": "Mi distancia de la obsesión", "template": "Lo que suelo hacer con la obsesión: {{trampas}}. La obsesión: {{obsesion}}. El nombre de la historia: {{historia}}. Mi frase: {{frase}}.", "content": "Es normal que la obsesión vuelva: cada vez es una nueva oportunidad para practicar. Estas prácticas complementan, no reemplazan, la exposición con prevención de respuesta que se planifica con tu psicólogo/a." } ]$steps$::jsonb),
  ('cuadro-toc-tcc-responsabilidad', 'TOC: revisar la amenaza y la responsabilidad', 'Un ejercicio de TCC para revisar tres trampas del TOC: sobreestimar el peligro, sentirte responsable de todo y creer que pensar es hacer.', 'custom', 'tcc', 'todos', 'cuadros', 14, 335,
   $steps$[ { "id": "intro", "type": "info", "title": "Tres trampas del TOC", "content": "En el TOC suelen aparecer tres formas de pensar que hacen que una duda se sienta insoportable:\n\n- **Sobreestimar la amenaza:** sentir que algo malo es muy probable o muy grave.\n- **Responsabilidad inflada:** sentir que, si pasa algo, va a ser enteramente tu culpa, y que tenés que evitarlo a toda costa.\n- **Fusión pensamiento-acción:** creer que pensar algo lo hace más probable, o que pensarlo es tan grave como hacerlo.\n\nEn este ejercicio vas a revisarlas con calma. No es para convencerte de que «no va a pasar nada», sino para mirar la situación de forma más equilibrada." }, { "id": "aclaracion", "type": "info", "title": "Importante", "content": "Este ejercicio es para hacerlo **con calma, una vez**, y no para repetirlo cada vez que aparece la obsesión. Si lo usás para tranquilizarte una y otra vez, puede convertirse en un ritual más.\n\nEl tratamiento central del TOC es la **exposición con prevención de respuesta (EPR)**, que se planifica en sesión con tu psicólogo/a, de forma gradual. No hace falta que empieces exposiciones por tu cuenta.\n\nSi en algún momento estás en crisis, sentís que no podés más o pensás en hacerte daño, **pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "situacion", "type": "text", "prompt": "Elegí una situación que te genere una obsesión. ¿Qué temés que pase?", "placeholder": "Por ejemplo: «si no reviso la hornalla, se incendia la casa»" }, { "id": "prob_antes", "type": "scale", "prompt": "Cuando aparece la obsesión, ¿qué tan probable sentís que pase eso?", "min": 0, "max": 100, "min_label": "Imposible", "max_label": "Seguro" }, { "id": "cadena_info", "type": "info", "title": "Las preguntas de probabilidad", "content": "Para que lo que temés suceda, en general tienen que darse **varias cosas seguidas**. Por ejemplo: que la hornalla quede abierta, que nadie lo note, que haya algo cerca que se prenda, que el fuego se extienda…\n\nCada paso tiene su propia probabilidad, y todas juntas suelen dar algo **mucho menos probable** de lo que se siente.\n\nPreguntate también:\n\n- ¿Cuántas veces temí esto y qué pasó realmente?\n- ¿Qué pensaría alguien sin TOC en esta misma situación?\n- Si pasara, ¿cuánto podría hacer para afrontarlo?" }, { "id": "cadena", "type": "list", "prompt": "Escribí los pasos que tendrían que darse, uno tras otro, para que pase lo que temés.", "count": 5, "min": 3 }, { "id": "prob_despues", "type": "scale", "prompt": "Mirando toda la cadena, ¿qué tan probable te parece ahora?", "min": 0, "max": 100, "min_label": "Imposible", "max_label": "Seguro" }, { "id": "torta_info", "type": "info", "title": "La torta de la responsabilidad", "content": "Imaginá que lo que temés sí pasara. ¿Sería todo culpa tuya?\n\nHacé una lista de **todas las personas y factores** que podrían influir: otras personas, el azar, el estado de los objetos, la situación, el tiempo.\n\nDespués, repartí la «torta» del 100 %: asignale a cada factor un porcentaje, y **dejá tu parte para el final**.\n\nEs común que, al terminar, tu parte sea bastante más chica de lo que sentías al principio." }, { "id": "torta", "type": "text", "prompt": "Repartí la torta: escribí cada factor con su porcentaje, dejando tu parte para el final.", "placeholder": "Por ejemplo: la hornalla vieja 30 %, mi pareja que también cocina 20 %, azar 30 %, yo 20 %" }, { "id": "resp_antes", "type": "text", "prompt": "Antes de hacer la torta, ¿qué porcentaje de responsabilidad sentías que era tuya? ¿Y ahora?", "placeholder": "Antes: …%. Ahora: …%" }, { "id": "fusion", "type": "choice", "prompt": "Mito o realidad: «Si pienso que algo malo le va a pasar a alguien, es más probable que pase».", "options": [ "Mito", "Realidad" ], "feedback": { "Mito": "Correcto. Los pensamientos no mueven el mundo. Podés hacer la prueba: pensá que va a llover ahora mismo, y fijate si cambia algo. Pensar no es hacer.", "Realidad": "Así se siente con el TOC, pero los pensamientos no hacen que las cosas pasen. Pensar algo, incluso algo feo, no es lo mismo que hacerlo ni que desearlo." } }, { "id": "conclusion", "type": "text", "prompt": "Escribí una mirada más equilibrada sobre la situación, sin buscar certeza absoluta.", "placeholder": "Por ejemplo: «es poco probable y no depende solo de mí; puedo convivir con la duda»" }, { "id": "resumen", "type": "reflect", "title": "Lo que revisé", "template": "Lo que temo: {{situacion}}. La cadena: {{cadena}}. La torta de la responsabilidad: {{torta}}. Mi responsabilidad, antes y ahora: {{resp_antes}}. Mi mirada más equilibrada: {{conclusion}}.", "content": "Llevá esto a la próxima sesión: puede ayudar a planificar con tu psicólogo/a los pasos de exposición. Recordá no usar este ejercicio para asegurarte cada vez que aparece la duda." } ]$steps$::jsonb),
  ('cuadro-trauma-dbt-tolerancia', 'Atravesar momentos de mucha activación', 'Habilidades de DBT para tolerar el malestar cuando el cuerpo se activa mucho: TIPP, autocalmarte y aceptación radical.', 'custom', 'dbt', 'todos', 'cuadros', 13, 336,
   $steps$[ { "id": "intro", "type": "info", "title": "Cuando el cuerpo se dispara", "content": "Después de experiencias muy difíciles, el cuerpo a veces **se activa de golpe**: el corazón se acelera, aparece mucha tensión, enojo, miedo o ganas de escapar, a veces sin un motivo claro.\n\nLa Terapia Dialéctica Conductual (DBT) ofrece habilidades de **tolerancia al malestar**: maneras de atravesar ese momento sin hacer algo que te dañe o que empeore las cosas.\n\nEste ejercicio **no trabaja recuerdos** ni te pide contar lo que pasó. Solo se enfoca en qué hacer en el momento de la activación. Lo ideal es practicarlo cuando estás más tranquilo/a." }, { "id": "seguridad", "type": "info", "title": "Si necesitás ayuda urgente", "content": "Si estás en crisis, sentís que podés hacerte daño o que no estás a salvo, **pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nSi mientras hacés el ejercicio el malestar sube mucho, podés pararlo en cualquier momento.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "activacion", "type": "scale", "prompt": "¿Cuánta tensión o activación sentís en este momento?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Muchísima", "maps_to": "emotion_before" }, { "id": "tipp", "type": "info", "title": "TIPP: bajar la activación con el cuerpo", "content": "Cuando la activación es muy alta, TIPP ayuda a bajarla rápido a través del cuerpo:\n\n- **Temperatura:** agua fría en la cara unos segundos, o algo frío en la nuca o las muñecas.\n- **Intenso ejercicio:** unos minutos de movimiento fuerte (subir escaleras, saltar, caminar rápido).\n- **Pausar la respiración:** exhalaciones más largas que las inhalaciones.\n- **Progresiva relajación:** tensar y soltar grupos de músculos.\n\n**Precauciones:** el agua fría y el ejercicio intenso cambian el ritmo cardíaco. Si tenés problemas de corazón, presión baja, trastornos de la alimentación u otra condición médica, o estás embarazada, **consultá antes con tu médico/a** y usá solo la respiración y la relajación." }, { "id": "tipp_elegir", "type": "checklist", "prompt": "¿Cuáles de estas habilidades te gustaría probar? Marcá las que sean seguras para vos.", "options": [ "Temperatura (agua fría)", "Ejercicio intenso", "Respiración pausada", "Relajación muscular" ], "min": 1 }, { "id": "relajacion", "type": "timed_info", "title": "Respirar y soltar", "content": "Vamos a practicar las dos partes más suaves de TIPP.\n\n- **Inhalá** contando hasta 4 y **exhalá lento** contando hasta 6.\n- En la próxima inhalación, **apretá los puños** fuerte unos segundos.\n- Al exhalar, **soltalos** y notá la diferencia.\n- Repetí con los hombros (subilos hacia las orejas y soltalos) y después con la cara.\n\nSi en algún momento te sentís incómodo/a, abrí los ojos, mirá a tu alrededor y respirá normal.", "seconds": 120 }, { "id": "calmarme", "type": "list", "prompt": "¿Qué cosas te ayudan a calmarte a través de los sentidos? (una música, un olor, una manta, una bebida tibia)", "count": 4, "min": 2 }, { "id": "aceptacion_info", "type": "info", "title": "Aceptación radical, con cuidado", "content": "Hay cosas que no podemos cambiar: lo que ya pasó, o lo que sentimos en este momento. Pelear contra eso («esto no debería estar pasando») suele sumar sufrimiento al dolor.\n\nLa aceptación radical es **reconocer la realidad tal como es**, para poder decidir qué hacer desde ahí.\n\nEs muy importante aclararlo: **aceptar no es aprobar**. No significa que lo que pasó estuvo bien, que fue tu culpa, que tenés que perdonar ni que no te importa. Podés aceptar que algo ocurrió y, al mismo tiempo, sentir que fue injusto.\n\nEs una práctica que lleva tiempo, y está bien si hoy no sale." }, { "id": "aceptar_quiz", "type": "choice", "prompt": "Según DBT, ¿qué significa «aceptar radicalmente» algo doloroso?", "options": [ "Que estoy de acuerdo con lo que pasó", "Reconocer que pasó, aunque no me guste", "Que ya no me tiene que doler" ], "feedback": { "Que estoy de acuerdo con lo que pasó": "No. Aceptar no es aprobar ni justificar. Podés reconocer que algo pasó y seguir sintiendo que estuvo mal.", "Reconocer que pasó, aunque no me guste": "Sí. Es dejar de pelear con la realidad para poder decidir qué hacer desde ahí. No implica estar de acuerdo.", "Que ya no me tiene que doler": "No. El dolor puede seguir. La aceptación busca bajar el sufrimiento extra de pelear con lo que no se puede cambiar." } }, { "id": "frase_aceptacion", "type": "text", "prompt": "Escribí una frase de aceptación que te resulte amable, sobre el momento presente.", "placeholder": "Por ejemplo: «Ahora estoy muy activado/a. Es así en este momento. Puedo atravesarlo.»" }, { "id": "activacion_despues", "type": "scale", "prompt": "Ahora, ¿cuánta tensión o activación sentís?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Muchísima", "maps_to": "emotion_after" }, { "id": "resumen", "type": "reflect", "title": "Mi plan para la activación", "template": "Habilidades TIPP que voy a usar: {{tipp_elegir}}. Lo que me calma: {{calmarme}}. Mi frase de aceptación: {{frase_aceptacion}}.", "content": "Si notás que la activación aparece muy seguido o es muy intensa, contáselo a tu psicólogo/a: es parte de lo que se trabaja en terapia, a tu ritmo." } ]$steps$::jsonb),
  ('cuadro-trauma-act-autocompasion', 'Tratarme con amabilidad frente a la culpa', 'Prácticas de ACT para mirar la culpa y la vergüenza desde el yo observador y responderte con más amabilidad, sin revisar lo que pasó.', 'custom', 'act', 'todos', 'cuadros', 14, 337,
   $steps$[ { "id": "intro", "type": "info", "title": "Culpa y vergüenza", "content": "Después de una experiencia muy difícil, muchas personas cargan con **culpa** («tendría que haber hecho algo») o **vergüenza** («algo está mal en mí»). Son reacciones muy frecuentes y comprensibles, aunque no digan la verdad sobre quién sos.\n\nEn este ejercicio vas a practicar dos cosas desde la Terapia de Aceptación y Compromiso (ACT): **mirar esos pensamientos desde un lugar más amplio** y **responderte con amabilidad**.\n\n**No vas a contar ni revisar lo que pasó.** Si en algún momento te sentís desbordado/a, podés frenar y volver otro día." }, { "id": "seguridad", "type": "info", "title": "Si necesitás ayuda urgente", "content": "Si estás en crisis, sentís que podés hacerte daño o que no estás a salvo, **pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "malestar", "type": "scale", "prompt": "¿Cuánto malestar sentís en este momento?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Muchísimo", "maps_to": "emotion_before" }, { "id": "voz", "type": "checklist", "prompt": "¿Cómo te suele hablar tu mente cuando aparece la culpa o la vergüenza? Marcá lo que reconozcas.", "options": [ "«Fue mi culpa»", "«Tendría que haber reaccionado distinto»", "«Soy débil»", "«Algo está mal en mí»", "«No merezco estar bien»", "«Nadie me entendería»", "Otra cosa" ], "min": 1 }, { "id": "observador_info", "type": "info", "title": "El yo observador", "content": "Hay una parte tuya que **nota** lo que pensás y sentís. Los pensamientos cambian, las emociones van y vienen, pero esa parte que observa sigue ahí.\n\nUna imagen que ayuda: **vos sos el cielo, y los pensamientos y emociones son el clima**. Puede haber tormenta, nubes negras o viento fuerte, pero el cielo no se rompe ni se ensucia con el clima.\n\nDesde ese lugar podés notar: «ahí está otra vez la culpa», sin tener que creerle ni pelearte con ella." }, { "id": "cielo", "type": "timed_info", "title": "El cielo y el clima", "content": "Sentate cómodo/a, con los pies apoyados en el piso.\n\n- **Notá tu respiración**, sin cambiarla.\n- Si aparece un pensamiento de culpa o de vergüenza, **notalo como una nube**: «ahí hay un pensamiento».\n- No hace falta empujarlo ni analizarlo. Dejá que esté y que pase cuando pase.\n- Recordá que **vos sos el cielo** que contiene esas nubes.\n\nSi aparece un recuerdo, abrí los ojos, mirá cinco cosas a tu alrededor y volvé a la respiración.", "seconds": 90 }, { "id": "autocompasion_info", "type": "info", "title": "Autocompasión", "content": "La autocompasión es **tratarte como tratarías a alguien querido que está sufriendo**. No es lástima ni excusas: es reconocer el dolor y responderle con calidez.\n\nTiene tres partes:\n\n- **Notar:** «esto duele mucho».\n- **Humanidad compartida:** «no soy la única persona que se siente así».\n- **Amabilidad:** «¿qué necesito escuchar ahora?».\n\nAl principio puede sentirse raro o incluso incómodo. Es esperable, sobre todo si estás acostumbrado/a a tratarte con dureza." }, { "id": "mano", "type": "timed_info", "title": "Una mano en el pecho", "content": "Apoyá una mano en el pecho, o donde te resulte reconfortante (la panza, el brazo, la mejilla). Sentí el calor y el peso suave de tu mano.\n\nDecite despacio, en voz baja o por dentro:\n\n- **«Esto es muy difícil.»**\n- **«Muchas personas se sienten así después de algo así.»**\n- **«Que pueda ser amable conmigo en este momento.»**\n\nSi alguna frase no te sale o no te la creés, está bien. Probá con palabras que te suenen más propias.", "seconds": 90 }, { "id": "frases", "type": "list", "prompt": "Escribí dos o tres frases amables que te gustaría decirte cuando aparece la culpa.", "count": 3, "min": 2 }, { "id": "carta", "type": "text", "prompt": "Escribí una carta corta como si te la mandara un amigo/a compasivo/a. Sin contar lo que pasó: solo lo que te diría.", "placeholder": "Querido/a…, sé que estás cargando con mucho. Lo que sentís tiene sentido…" }, { "id": "como_quedaste", "type": "text", "prompt": "¿Cómo te quedaste después de leer esa carta?", "placeholder": "Lo que noté" }, { "id": "malestar_despues", "type": "scale", "prompt": "Ahora, ¿cuánto malestar sentís?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Muchísimo", "maps_to": "emotion_after" }, { "id": "resumen", "type": "reflect", "title": "Lo que me llevo", "template": "Lo que me dice la culpa: {{voz}}. Lo que quiero decirme: {{frases}}. Lo que me diría alguien que me quiere: {{carta}}.", "content": "La culpa y la vergüenza después de una experiencia difícil se trabajan en terapia, con cuidado y a tu ritmo. Si te sirve, compartí esta carta con tu psicólogo/a." } ]$steps$::jsonb),
  ('cuadro-duelo-act-valores', 'Llevar a quien perdí en lo que hago', 'Un ejercicio de ACT para hacerle lugar al dolor y honrar a quien perdiste a través de tus valores y acciones.', 'custom', 'act', 'todos', 'cuadros', 13, 338,
   $steps$[ { "id": "intro", "type": "info", "title": "El dolor y el amor", "content": "Cuando perdemos a alguien, el dolor puede sentirse enorme. Desde la Terapia de Aceptación y Compromiso (ACT) se propone mirarlo así: **el dolor y el amor son dos caras de la misma moneda**. Duele tanto porque esa persona te importaba.\n\nNo se trata de dejar de sentir dolor ni de «superar» la pérdida. Se trata de **hacerle lugar** y, al mismo tiempo, encontrar formas de seguir llevando a esa persona con vos: en lo que te enseñó y en cómo elegís vivir.\n\nAndá a tu ritmo. Podés saltear lo que hoy no puedas responder." }, { "id": "seguridad", "type": "info", "title": "Si te sentís muy mal", "content": "Si el dolor se vuelve insoportable, sentís que no podés seguir o pensás en hacerte daño o en reunirte con quien perdiste, **pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano. También podés avisarle a alguien de confianza.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "dolor", "type": "scale", "prompt": "Antes de empezar, ¿cuánto dolor sentís ahora?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Muchísimo", "maps_to": "emotion_before" }, { "id": "lugar", "type": "timed_info", "title": "Hacerle lugar al dolor", "content": "Sentate cómodo/a y respirá con calma.\n\n- **Notá dónde sentís el dolor** en el cuerpo: el pecho, la garganta, la panza.\n- Si podés, **apoyá una mano ahí**, con suavidad.\n- Respirá hacia ese lugar, como **haciéndole espacio**, sin intentar que se vaya.\n- Si aparecen lágrimas, recuerdos o pensamientos, dejalos estar.\n\nPodés decirte: «esto duele porque te quise».", "seconds": 90 }, { "id": "nombre", "type": "text", "prompt": "¿A quién perdiste? Podés escribir su nombre o cómo te gusta llamarle.", "placeholder": "Nombre", "optional": true }, { "id": "ensenanzas", "type": "list", "prompt": "¿Qué te enseñó o te dejó esa persona? (una forma de ser, una costumbre, algo que decía)", "count": 3, "min": 1 }, { "id": "valores_info", "type": "info", "title": "De lo que te dejó a lo que hacés", "content": "Muchas veces, lo que más queríamos de alguien se parece a **lo que valoramos**: su generosidad, su humor, su forma de cuidar a los demás, su amor por la tierra o la música.\n\nUna forma de honrar a quien se fue es **llevar esos valores a tus acciones**: cocinar su receta para la familia, ayudar a alguien como esa persona lo hacía, retomar algo que compartían.\n\nNo es reemplazar a nadie ni «seguir adelante» como si nada. Es que el vínculo siga vivo de otra manera, **en lo que vos hacés**." }, { "id": "valor", "type": "text", "prompt": "De lo que te dejó, ¿qué te gustaría mantener vivo en tu forma de vivir?", "placeholder": "Por ejemplo: su manera de recibir a todos en casa" }, { "id": "accion", "type": "text", "prompt": "¿Qué acción chica podrías hacer este mes para honrar eso?", "placeholder": "Por ejemplo: invitar a mis hermanos a almorzar el domingo, como hacía ella" }, { "id": "barrera", "type": "choice", "prompt": "Si al hacerlo aparece mucho dolor, ¿qué te parece más cercano a lo que propone ACT?", "options": [ "Esperar a que deje de doler para hacerlo", "Hacerlo con el dolor, a un ritmo posible", "Obligarme a hacerlo sin sentir nada" ], "feedback": { "Esperar a que deje de doler para hacerlo": "Es comprensible, pero el dolor puede tardar. ACT propone no esperar a que se vaya, sino hacerle lugar mientras hacés lo que importa.", "Hacerlo con el dolor, a un ritmo posible": "Sí. El dolor puede acompañarte mientras honrás a esa persona. Y siempre podés achicar el paso si es mucho.", "Obligarme a hacerlo sin sentir nada": "No hace falta dejar de sentir. Las emociones pueden estar presentes; no tenés que taparlas." } }, { "id": "mensaje", "type": "text", "prompt": "Si pudieras decirle algo a esa persona sobre cómo querés llevarla con vos, ¿qué le dirías?", "placeholder": "Lo que le diría", "optional": true }, { "id": "dolor_despues", "type": "scale", "prompt": "Ahora, ¿cuánto dolor sentís?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Muchísimo", "maps_to": "emotion_after" }, { "id": "resumen", "type": "reflect", "title": "Llevarte conmigo", "template": "Lo que me dejaste: {{ensenanzas}}. Lo que quiero mantener vivo: {{valor}}. Cómo lo voy a honrar: {{accion}}.", "content": "Que el dolor siga presente no significa que lo estés haciendo mal. Si querés, compartí esto con tu psicólogo/a en la próxima sesión." } ]$steps$::jsonb),
  ('cuadro-duelo-tcc-culpa', 'Duelo: cuando aparecen la culpa y los «hubiera»', 'Un ejercicio de TCC, con cuidado, para revisar los pensamientos de culpa en el duelo: lo que sabías entonces y lo que sabés ahora.', 'custom', 'tcc', 'todos', 'cuadros', 14, 339,
   $steps$[ { "id": "intro", "type": "info", "title": "Los «hubiera»", "content": "En el duelo es muy común que aparezcan pensamientos como «si lo hubiera llevado antes al médico», «tendría que haber estado ahí», «le dije algo feo la última vez».\n\nLa culpa **tiene sentido**: muchas veces es una forma del amor y de las ganas de que las cosas hubieran sido distintas. No es una señal de que hiciste algo mal.\n\nEn este ejercicio vas a mirar esos pensamientos con calma y con cuidado. **No se trata de convencerte de nada** ni de apurar el proceso, sino de ver si la culpa está siendo justa con vos. Si en algún momento es demasiado, podés frenar." }, { "id": "seguridad", "type": "info", "title": "Si te sentís muy mal", "content": "Si el dolor o la culpa se vuelven insoportables, sentís que no podés seguir o pensás en hacerte daño, **pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano. También podés avisarle a alguien de confianza.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "culpa_antes", "type": "scale", "prompt": "¿Cuánta culpa sentís en este momento?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Muchísima", "maps_to": "emotion_before" }, { "id": "hubiera", "type": "text", "prompt": "Escribí uno de tus «hubiera» o pensamientos de culpa, con tus palabras.", "placeholder": "Por ejemplo: «si hubiera insistido para que fuera al médico, seguiría acá»" }, { "id": "creencia_antes", "type": "scale", "prompt": "¿Cuánto creés ese pensamiento ahora?", "min": 0, "max": 100, "min_label": "Nada", "max_label": "Totalmente" }, { "id": "sesgo_info", "type": "info", "title": "Lo que sabías entonces", "content": "Hay algo que se llama **sesgo retrospectivo**: cuando miramos hacia atrás, sabiendo cómo terminó todo, las señales parecen clarísimas. Pero en ese momento **no tenías la información que tenés hoy**.\n\nEn su momento, probablemente:\n\n- No sabías lo que iba a pasar.\n- Había otras explicaciones posibles para lo que veías.\n- Estabas tomando decisiones con lo que tenías, con cansancio, preocupaciones u otras responsabilidades.\n\nJuzgar una decisión de ayer con lo que sabés hoy no es justo con quien eras entonces." }, { "id": "entonces", "type": "text", "prompt": "En ese momento, antes de saber cómo terminaría, ¿qué sabías y qué pensabas que estaba pasando?", "placeholder": "Por ejemplo: pensé que era un resfrío, como otras veces" }, { "id": "ahora", "type": "text", "prompt": "¿Qué sabés ahora que no sabías entonces?", "placeholder": "Lo que sé ahora" }, { "id": "otros_factores", "type": "checklist", "prompt": "¿Qué otras cosas influyeron en lo que pasó, además de vos? Marcá las que correspondan.", "options": [ "La enfermedad o la situación en sí", "Decisiones de otras personas", "Lo que la persona eligió o quiso", "El sistema de salud o los tiempos", "El azar o lo imprevisible", "Cosas que nadie podía saber", "Otra cosa" ], "min": 1 }, { "id": "doble_info", "type": "info", "title": "El doble estándar", "content": "Muchas veces somos **mucho más duros/as con nosotros/as** que con cualquier otra persona.\n\nImaginá que un amigo/a querido/a te cuenta esta misma historia, con los mismos detalles, y te dice que siente que fue su culpa. ¿Qué le dirías? ¿Le dirías que es culpable, o lo/la mirarías con más comprensión?\n\nSi tu respuesta para otra persona sería más amable, vale la pena preguntarte **por qué con vos usás otra vara**." }, { "id": "amigo", "type": "text", "prompt": "¿Qué le dirías a ese amigo/a si te contara lo mismo?", "placeholder": "Lo que le diría" }, { "id": "equilibrado", "type": "text", "prompt": "Escribí una mirada más justa sobre lo que pasó, que tenga en cuenta todo lo anterior y tu dolor.", "placeholder": "Por ejemplo: «hice lo que pude con lo que sabía; lo que siento es porque la quería»" }, { "id": "culpa_despues", "type": "scale", "prompt": "Ahora, ¿cuánta culpa sentís?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Muchísima", "maps_to": "emotion_after" }, { "id": "resumen", "type": "reflect", "title": "Una mirada más justa", "template": "Mi «hubiera»: {{hubiera}}. Lo que sabía entonces: {{entonces}}. Lo que sé ahora: {{ahora}}. Otras cosas que influyeron: {{otros_factores}}. Lo que le diría a un amigo/a: {{amigo}}. Mi mirada más justa: {{equilibrado}}.", "content": "Es normal que la culpa no desaparezca de un día para el otro. Si sentís que hay algo que te pesa mucho, o algo que te gustaría reparar, es un muy buen tema para charlar con tu psicólogo/a." } ]$steps$::jsonb),
  ('cuadro-burnout-act-valores', 'Burnout: volver a lo que te importa', 'Desde ACT: distinguí valores de metas, reconectá con lo que te importa dentro y fuera del trabajo y elegí una acción y un «no» alineados.', 'custom', 'act', 'todos', 'cuadros', 15, 340,
   $steps$[ { "id": "intro", "type": "info", "title": "Cuando el trabajo se come todo", "content": "Con el agotamiento es común sentir que el día se reduce a cumplir, apagar incendios y llegar a la noche sin resto. De a poco se pierde de vista **para qué** hacés lo que hacés, y también lo que te importa fuera del trabajo.\n\nEste ejercicio viene de la **Terapia de Aceptación y Compromiso (ACT)**. No busca que rindas más ni que te guste todo de tu trabajo. Busca que vuelvas a ver tu brújula: tus **valores**, y que elijas una acción chica en esa dirección.\n\nTambién vas a pensar en un **«no»**: a veces cuidar lo que te importa implica dejar de hacer algo." }, { "id": "seguridad", "type": "info", "title": "Antes de empezar", "content": "**Si estás en crisis, sentís que no das más o aparecen pensamientos de hacerte daño, pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos.\n\nEste ejercicio no reemplaza la consulta médica si tenés síntomas físicos que te preocupan." }, { "id": "valores_metas", "type": "info", "title": "Valores y metas no son lo mismo", "content": "Una **meta** se cumple y se tacha: entregar el informe, conseguir el ascenso, terminar el año. Un **valor** es una dirección que nunca se termina: ser una persona confiable, aprender, cuidar a otros, crear, ser justo/a.\n\nEn el burnout muchas veces vivimos solo de metas: siempre hay una más, y cuando se cumple, aparece la siguiente. Los valores, en cambio, se pueden vivir **hoy**, en acciones chicas, aunque la meta esté lejos.\n\nPor ejemplo: la meta es «cerrar todos los pendientes»; el valor puede ser «hacer un trabajo cuidadoso» o «ayudar a las personas que atiendo»." }, { "id": "quiz_valor", "type": "choice", "prompt": "¿Cuál de estas frases describe un valor (y no una meta)?", "options": [ "Terminar el proyecto antes de fin de mes", "Tratar con respeto a las personas con las que trabajo", "Conseguir un aumento este año" ], "feedback": { "Terminar el proyecto antes de fin de mes": "Eso es una meta: tiene un final y se puede tachar. Puede estar al servicio de un valor, como «ser responsable» o «colaborar con mi equipo».", "Tratar con respeto a las personas con las que trabajo": "Exacto. Es una dirección que no se termina y que podés vivir hoy mismo, en cualquier interacción, aunque el día sea difícil.", "Conseguir un aumento este año": "Eso es una meta. Puede ser importante, y detrás quizás haya valores como «cuidar a mi familia» o «que mi trabajo sea reconocido»." } }, { "id": "valores_trabajo", "type": "checklist", "prompt": "Pensando en tu trabajo, ¿qué te importó alguna vez o te sigue importando? Marcá hasta 3.", "options": [ "Ayudar o cuidar a otras personas", "Aprender y crecer", "Hacer las cosas con calidad", "Colaborar con un equipo", "Crear o resolver problemas", "Ser justo/a y honesto/a", "Tener autonomía", "Sostener a mi familia" ], "min": 1, "max": 3 }, { "id": "valores_fuera", "type": "list", "prompt": "Fuera del trabajo, ¿qué áreas de tu vida te importan y quedaron relegadas?", "help": "Por ejemplo: vínculos, salud y cuerpo, descanso, juego, espiritualidad, comunidad, aprender algo por gusto.", "count": 3, "min": 1 }, { "id": "distancia", "type": "scale", "prompt": "Hoy, ¿qué tan cerca sentís que estás viviendo de acuerdo con lo que te importa?", "min": 0, "max": 10, "min_label": "Muy lejos", "max_label": "Muy cerca" }, { "id": "pausa_valores", "type": "timed_info", "title": "Un minuto para conectar", "content": "Cerrá los ojos o bajá la mirada. Respirá con calma.\n\nTraé a la mente un momento, aunque sea chiquito, en el que hiciste algo que te importaba de verdad: ayudar a alguien, aprender algo, compartir con quien querés.\n\n- ¿Dónde estabas?\n- ¿Qué hiciste?\n- ¿Qué sentiste en el cuerpo?\n\nNo hace falta que sea un gran logro. Solo notá que esa parte tuya sigue ahí, aunque esté cansada.", "seconds": 90 }, { "id": "accion", "type": "text", "prompt": "Elegí una acción chica, para esta semana, que vaya en la dirección de uno de tus valores.", "help": "Que sea concreta y posible aunque estés con poca energía. Por ejemplo: «el jueves almuerzo con mi compañera sin hablar de pendientes» o «el sábado camino 20 minutos».", "placeholder": "Qué, cuándo y dónde…" }, { "id": "no_alineado", "type": "text", "prompt": "¿A qué podrías decir «no» (o «ahora no») para hacerle lugar a lo que te importa?", "help": "Un «no» alineado con valores no es egoísmo: es elegir. Por ejemplo: no responder mensajes del trabajo durante la cena para estar con tu familia.", "placeholder": "Voy a decir que no a…" }, { "id": "obstaculos", "type": "text", "prompt": "¿Qué pensamientos o sensaciones podrían aparecer y frenarte? ¿Cómo los vas a dejar estar sin que manejen?", "help": "Por ejemplo: culpa, «si no contesto van a pensar que no me comprometo». Podés notarlos, nombrarlos («apareció la culpa») y hacer igual tu acción.", "optional": true }, { "id": "cierre", "type": "reflect", "title": "Tu brújula para esta semana", "template": "En el trabajo me importa: {{valores_trabajo}}. Fuera del trabajo quiero hacerle lugar a: {{valores_fuera}}. Mi acción comprometida: {{accion}}. Mi «no» alineado: {{no_alineado}}.", "content": "No se trata de hacerlo perfecto. Si no sale, no es un fracaso: es información. Volvé a tu brújula y elegí de nuevo. Podés traer lo que pasó a la próxima sesión." } ]$steps$::jsonb),
  ('cuadro-burnout-dbt-limites', 'Burnout: poner límites con DEAR MAN', 'Desde DBT: prepará una conversación real para poner un límite o pedir un cambio en el trabajo, cuidando la relación y tu autorrespeto.', 'custom', 'dbt', 'todos', 'cuadros', 15, 341,
   $steps$[ { "id": "intro", "type": "info", "title": "Pedir y decir que no, con un guion", "content": "Muchas personas con agotamiento laboral saben qué límite necesitan, pero se traban a la hora de decirlo: miedo a quedar mal, a un conflicto o a perder el trabajo.\n\nLa **Terapia Dialéctica Conductual (DBT)** tiene habilidades de **efectividad interpersonal** que ayudan a preparar esas conversaciones. Hoy vas a usar dos:\n\n- **DEAR MAN**, para pedir algo o decir que no con claridad.\n- **FAST**, para cuidar tu autorrespeto durante la conversación.\n\nAl final vas a tener un **guion** de una conversación real. No garantiza que la otra persona acepte, pero aumenta las chances de que te escuchen y de que salgas sintiéndote bien con cómo lo dijiste." }, { "id": "seguridad", "type": "info", "title": "Antes de empezar", "content": "**Si estás en crisis, sentís que no das más o aparecen pensamientos de hacerte daño, pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos.\n\nSi en tu trabajo hay situaciones de acoso, maltrato o riesgo, hablalo en sesión: además de habilidades, puede hacer falta otro tipo de apoyo." }, { "id": "situacion", "type": "text", "prompt": "¿Qué situación del trabajo te gustaría abordar? ¿Con quién tendrías que hablar?", "placeholder": "Por ejemplo: con mi jefa, por los mensajes que me manda los fines de semana" }, { "id": "dear_man_info", "type": "info", "title": "DEAR MAN, paso a paso", "content": "- **D — Describir:** contá los hechos, sin juicios. «En el último mes recibí pedidos urgentes los sábados».\n- **E — Expresar:** decí cómo te afecta, en primera persona. «Me cuesta descansar y llego el lunes agotado/a».\n- **A — Afirmar:** pedí con claridad o decí que no. «Te pido que lo que surja el fin de semana quede para el lunes».\n- **R — Reforzar:** mostrá qué gana la otra persona. «Así rindo mejor durante la semana».\n- **M — Mantenerte en foco:** si te desvían, volvé a tu pedido con calma (el «disco rayado»).\n- **A — Aparentar confianza:** postura firme, tono tranquilo, mirada, aunque por dentro tengas nervios.\n- **N — Negociar:** estate dispuesto/a a escuchar alternativas. «¿Qué te parece si lo urgente de verdad me lo avisás por llamada?»" }, { "id": "d_describir", "type": "text", "prompt": "D — Describir: ¿qué hechos vas a contar, sin juicios ni adjetivos?", "placeholder": "En las últimas semanas…" }, { "id": "e_expresar", "type": "text", "prompt": "E — Expresar: ¿cómo te afecta? Usá «yo siento» o «a mí me pasa».", "placeholder": "Me siento… / Me cuesta…" }, { "id": "a_afirmar", "type": "text", "prompt": "A — Afirmar: ¿qué vas a pedir o a qué vas a decir que no, en una frase clara?", "placeholder": "Te pido que… / No voy a poder…", "help": "Pensá en un pedido concreto y realista. «Que me respeten más» es difícil de medir; «que los pedidos del viernes a la tarde queden para el lunes» es claro." }, { "id": "r_reforzar", "type": "text", "prompt": "R — Reforzar: ¿qué gana la otra persona o el equipo si acepta?", "placeholder": "Así…" }, { "id": "n_negociar", "type": "text", "prompt": "N — Negociar: ¿qué alternativa podrías ofrecer o aceptar si te dicen que no?", "placeholder": "Podría aceptar que…" }, { "id": "fast_info", "type": "info", "title": "FAST: cuidar tu autorrespeto", "content": "Mientras pedís, también importa cómo salís vos de la conversación:\n\n- **F — (ser) Justo/a (Fair):** con la otra persona y también con vos.\n- **A — (sin) Disculpas de más (Apologies):** no pidas perdón por tener un límite o por pedir algo razonable.\n- **S — Sostener tus valores (Stick to values):** no cedas en lo que es importante para vos solo para evitar incomodidad.\n- **T — (ser) Veraz (Truthful):** no exageres ni inventes excusas. Lo que necesitás alcanza como razón.\n\nUn buen resultado no es solo «me dijeron que sí». También es «lo dije de una forma de la que me siento orgulloso/a»." }, { "id": "fast_check", "type": "checklist", "prompt": "¿Qué te gustaría cuidar especialmente en esta conversación?", "options": [ "No pedir perdón de más", "No inventar excusas", "No ceder en lo esencial por incomodidad", "Ser justo/a también conmigo", "Volver a mi pedido si me desvían" ], "min": 1, "max": 5 }, { "id": "ensayo", "type": "timed_info", "title": "Ensayá en voz alta", "content": "Tomate dos minutos para decir tu guion en voz alta, como si la otra persona estuviera enfrente. Si podés, hacelo frente a un espejo.\n\n- Mantené la postura firme y los hombros sueltos.\n- Hablá un poco más despacio de lo habitual.\n- Si te trabás, respirá y volvé a la frase de **Afirmar**.\n\nNo tiene que salir perfecto. Ensayar baja los nervios y te ayuda a encontrar tus propias palabras.", "seconds": 120 }, { "id": "cuando", "type": "text", "prompt": "¿Cuándo y dónde vas a tener la conversación? ¿Hace falta pedir un momento a solas?", "placeholder": "Por ejemplo: el martes después de la reunión, en su oficina" }, { "id": "guion", "type": "reflect", "title": "Tu guion", "template": "Con quién y sobre qué: {{situacion}}.\n\nDescribir: {{d_describir}}\n\nExpresar: {{e_expresar}}\n\nAfirmar: {{a_afirmar}}\n\nReforzar: {{r_reforzar}}\n\nNegociar: {{n_negociar}}\n\nVoy a cuidar: {{fast_check}}. Cuándo: {{cuando}}.", "content": "Después de la conversación, anotá cómo te fue y qué aprendiste. Si la respuesta no fue la que esperabas, lo podés trabajar en sesión: a veces hace falta más de una conversación o buscar otros caminos." } ]$steps$::jsonb),
  ('cuadro-sueno-tcc-pensamientos', 'Sueño: los pensamientos que desvelan', 'Desde la TCC: identificá los pensamientos que te mantienen en vela, revisalos con otra mirada y programá un tiempo de preocupación lejos de la cama.', 'custom', 'tcc', 'todos', 'cuadros', 15, 342,
   $steps$[ { "id": "intro", "type": "info", "title": "Cuando la cabeza no se apaga", "content": "Muchas veces no es solo el cuerpo lo que no se duerme: es la cabeza. Aparecen pensamientos sobre el sueño mismo («si no me duermo ya, mañana va a ser un desastre») o sobre los problemas del día.\n\nEsos pensamientos generan **alerta**, y la alerta es lo opuesto al sueño. Se arma un círculo: no duermo → me preocupo → me activo → duermo peor.\n\nEn este ejercicio de **TCC** vas a hacer dos cosas:\n\n- **Revisar** los pensamientos sobre el sueño que te desvelan.\n- Programar un **tiempo de preocupación** de día, lejos de la cama, para que las preocupaciones tengan otro lugar." }, { "id": "seguridad", "type": "info", "title": "Antes de empezar", "content": "**Si estás en crisis o aparecen pensamientos de hacerte daño, pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos.\n\nSi roncás fuerte, te despertás ahogándote o tenés mucho sueño durante el día, consultá también con un médico: hay problemas de sueño que necesitan evaluación médica." }, { "id": "pensamientos", "type": "checklist", "prompt": "¿Cuáles de estos pensamientos te aparecen en la cama? Marcá los que quieras.", "options": [ "Si no duermo 8 horas, mañana es un desastre", "Ya perdí la capacidad de dormir bien", "Tengo que dormirme ya", "Mañana no voy a rendir nada", "Esto me va a enfermar", "Me quedan solo X horas para dormir", "Repaso todo lo que tengo que hacer mañana" ], "min": 1, "max": 7 }, { "id": "pensamiento_clave", "type": "text", "prompt": "Elegí el pensamiento que más te desvela y escribilo tal como aparece.", "placeholder": "Por ejemplo: «si no me duermo ya, mañana voy a hacer todo mal en el trabajo»" }, { "id": "creencia_antes", "type": "scale", "prompt": "¿Cuánto te creés ese pensamiento cuando aparece de noche?", "min": 0, "max": 100, "min_label": "Nada", "max_label": "Totalmente" }, { "id": "revisar_info", "type": "info", "title": "Revisar el pensamiento", "content": "De noche, cansados, los pensamientos suelen ser más **catastróficos** y absolutos. No se trata de pensar «en positivo», sino de mirar el pensamiento con datos.\n\nAlgunas preguntas útiles:\n\n- ¿Qué pasó **realmente** las otras veces que dormí mal? ¿Fue un desastre o fue un día más pesado?\n- ¿Hay días en que dormí poco y aun así pude hacer lo importante?\n- ¿Preocuparme ahora me ayuda a dormir o me activa más?\n- ¿Qué le diría a una persona querida que piensa esto?\n\nAlgo para tener presente: la cantidad de sueño que cada persona necesita varía, y el cuerpo suele compensar después de una mala noche." }, { "id": "evidencia", "type": "text", "prompt": "Mirando tu experiencia real, ¿qué pasó los días después de dormir mal?", "placeholder": "Por ejemplo: estuve más cansado/a, pero fui al trabajo y resolví lo urgente" }, { "id": "alternativo", "type": "text", "prompt": "Escribí un pensamiento más equilibrado, que puedas decirte de noche.", "help": "Que sea creíble para vos. Por ejemplo: «Dormir mal es incómodo, pero ya pasé muchos días así y salí adelante. Descansar en calma también me sirve».", "placeholder": "Puedo decirme…" }, { "id": "creencia_despues", "type": "scale", "prompt": "Ahora, ¿cuánto te creés el pensamiento original?", "min": 0, "max": 100, "min_label": "Nada", "max_label": "Totalmente" }, { "id": "tiempo_info", "type": "info", "title": "Un tiempo para preocuparte (que no sea en la cama)", "content": "El **tiempo de preocupación programado** consiste en reservar unos 15 minutos por día, a la tarde o temprano a la noche, para sentarte con papel y pensar en tus preocupaciones a propósito.\n\n- Elegí un lugar que **no sea el dormitorio**.\n- Que sea al menos un par de horas antes de acostarte.\n- Anotá cada preocupación y, si se puede, un próximo paso concreto. Si no tiene solución ahora, anotala igual.\n- Cuando se termina el tiempo, cerrá el cuaderno.\n\nSi de noche aparece una preocupación, podés decirte: «esto lo miro mañana en mi tiempo de preocupación». No siempre funciona de entrada; con la práctica, la cabeza aprende que hay otro momento para eso." }, { "id": "tiempo_plan", "type": "text", "prompt": "¿A qué hora y en qué lugar vas a hacer tu tiempo de preocupación esta semana?", "placeholder": "Por ejemplo: a las 19 h, en la mesa de la cocina, con un cuaderno" }, { "id": "frase_noche", "type": "text", "prompt": "¿Qué te vas a decir si una preocupación aparece cuando estás en la cama?", "placeholder": "Por ejemplo: «gracias, cabeza; esto lo anoto y lo miro mañana a las 19»" }, { "id": "cierre", "type": "reflect", "title": "Tu plan para las noches", "template": "Pensamiento que me desvela: «{{pensamiento_clave}}». Lo que muestra mi experiencia: {{evidencia}}. Me voy a decir: «{{alternativo}}». Mi tiempo de preocupación: {{tiempo_plan}}. Si aparece de noche: «{{frase_noche}}».", "content": "Esto se complementa con el diario de sueño y el control de estímulos que ves con tu psicólogo/a. Si después de un rato en la cama seguís muy despierto/a, levantarte a hacer algo tranquilo sigue siendo parte del plan." } ]$steps$::jsonb),
  ('cuadro-sueno-relajacion', 'Sueño: relajación muscular antes de acostarte', 'Una práctica guiada de relajación muscular progresiva y un escaneo corporal breve para bajar el ritmo antes de ir a la cama, sin presión por dormirte.', 'custom', 'regulacion', 'todos', 'cuadros', 15, 343,
   $steps$[ { "id": "intro", "type": "info", "title": "Bajar el ritmo, no obligarte a dormir", "content": "La **relajación muscular progresiva** consiste en tensar un grupo de músculos unos segundos y después soltarlo, prestando atención a la diferencia. Ayuda a reducir la activación del cuerpo y a notar dónde guardás tensión.\n\nUna aclaración importante: el objetivo **no es dormirte**. Si practicás pensando «esto tiene que hacerme dormir», la presión te activa más. El objetivo es **bajar el ritmo** y darle al cuerpo una señal de que el día terminó. Si después el sueño llega, bienvenido.\n\nHacelo sentado/a o acostado/a, idealmente en la última hora antes de acostarte, con luz baja." }, { "id": "seguridad", "type": "info", "title": "Antes de empezar", "content": "**Si estás en crisis o aparecen pensamientos de hacerte daño, pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos.\n\nSi tenés alguna lesión, dolor o problema muscular, tensá con suavidad o saltéate esa zona y solo prestale atención. Nunca tenses hasta que duela." }, { "id": "tension_antes", "type": "scale", "prompt": "Antes de empezar, ¿cuánta tensión sentís en el cuerpo?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Muchísima", "maps_to": "emotion_before" }, { "id": "manos_brazos", "type": "timed_info", "title": "Manos y brazos", "content": "Cerrá los puños y doblá los brazos, tensando manos, antebrazos y bíceps. Sostené unos **5 segundos**… notá la tensión.\n\nAhora **soltá** de golpe. Dejá caer los brazos. Quedate unos 15 segundos notando cómo se aflojan, como si pesaran más.\n\nRepetí una vez más: tensar… sostener… y soltar.", "seconds": 60 }, { "id": "cara_cuello", "type": "timed_info", "title": "Cara, hombros y cuello", "content": "Fruncí la frente, apretá los ojos y la mandíbula con suavidad. Sostené unos **5 segundos**… y soltá. Dejá que la frente se alise y la mandíbula se separe un poquito.\n\nAhora subí los hombros hacia las orejas. Sostené… y soltá, dejándolos caer.\n\nNotá la diferencia entre tensión y soltura. Respirá despacio.", "seconds": 60 }, { "id": "torso", "type": "timed_info", "title": "Pecho, espalda y abdomen", "content": "Inspirá hondo y llevá los hombros un poco hacia atrás, tensando el pecho y la espalda. Al mismo tiempo, tensá suavemente el abdomen. Sostené unos **5 segundos**…\n\nY soltá con una exhalación larga. Dejá que la respiración vuelva a su ritmo natural.\n\nQuedate notando cómo se mueve la panza al respirar, sin cambiar nada.", "seconds": 60 }, { "id": "piernas_pies", "type": "timed_info", "title": "Piernas y pies", "content": "Estirá las piernas, tensá muslos y pantorrillas y llevá las puntas de los pies hacia vos. Sostené unos **5 segundos**…\n\nY soltá. Dejá que las piernas descansen, pesadas, apoyadas.\n\nAhora curvá los dedos de los pies hacia abajo, sostené… y soltá.\n\nNotá todo el cuerpo apoyado, desde la cabeza hasta los pies.", "seconds": 60 }, { "id": "escaneo", "type": "timed_info", "title": "Escaneo corporal breve", "content": "Ahora sin tensar nada. Solo vas a recorrer el cuerpo con la atención, despacio.\n\n- Empezá por la coronilla, la frente, los ojos, la mandíbula.\n- Bajá por el cuello, los hombros, los brazos, las manos.\n- Pecho, panza, espalda.\n- Cadera, piernas, pies.\n\nSi encontrás una zona tensa, no hace falta arreglarla: solo notala y, al exhalar, imaginá que se ablanda un poquito. Si la mente se va a otra cosa, es normal: volvé con amabilidad a la parte del cuerpo donde estabas.", "seconds": 150 }, { "id": "tension_despues", "type": "scale", "prompt": "Y ahora, ¿cuánta tensión sentís en el cuerpo?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Muchísima", "maps_to": "emotion_after" }, { "id": "zonas", "type": "checklist", "prompt": "¿En qué zonas notaste más tensión guardada?", "options": [ "Mandíbula y cara", "Hombros y cuello", "Manos y brazos", "Pecho y espalda", "Abdomen", "Piernas y pies", "No noté una zona en particular" ], "min": 1, "max": 7 }, { "id": "experiencia", "type": "choice", "prompt": "¿Cómo fue la práctica para vos?", "options": [ "Me relajé bastante", "Me relajé un poco", "No noté mucho cambio", "Me puse más inquieto/a" ], "feedback": { "Me relajé bastante": "Qué bueno. Con la práctica, el cuerpo aprende a soltar más rápido. Podés sumarla a tu rutina de la última hora antes de acostarte.", "Me relajé un poco": "Es un buen comienzo. La relajación es una habilidad: suele salir mejor después de practicarla varios días seguidos.", "No noté mucho cambio": "Es frecuente al principio. No es una señal de que lo hiciste mal. Probala unos días más, en un momento sin apuro, y contalo en sesión.", "Me puse más inquieto/a": "A algunas personas prestar atención al cuerpo les genera inquietud al principio. Podés probar con los ojos abiertos o solo algunos grupos musculares, y hablarlo con tu psicólogo/a." } }, { "id": "plan", "type": "text", "prompt": "¿Cuándo y dónde vas a hacer esta práctica esta semana?", "help": "Mejor como parte de tu rutina para bajar el ritmo, antes de acostarte. Si la hacés en la cama, recordá: la idea es descansar, no forzar el sueño.", "placeholder": "Por ejemplo: a las 22.30, en el sillón, con luz baja" }, { "id": "cierre", "type": "reflect", "title": "Tu práctica", "template": "Donde más guardo tensión: {{zonas}}. Cómo me fue: {{experiencia}}. Mi plan: {{plan}}.", "content": "Recordá: esta práctica es para bajar el ritmo, no una obligación de dormir. Las noches en que no te dormís igual, seguís con tu plan de sueño de siempre." } ]$steps$::jsonb),
  ('cuadro-fobias-tcc-experimentos', 'Ansiedad social: experimentos conductuales', 'Desde la TCC: poné a prueba una predicción ansiosa en una situación social, soltando conductas de seguridad, y anotá qué pasó realmente.', 'custom', 'tcc', 'todos', 'cuadros', 15, 344,
   $steps$[ { "id": "intro", "type": "info", "title": "Poner a prueba lo que temés", "content": "En la ansiedad social, la mente suele hacer **predicciones**: «si hablo en la reunión, me voy a trabar y todos van a pensar que soy un desastre». Como evitamos la situación, o la atravesamos protegidos, nunca llegamos a comprobar si la predicción se cumple.\n\nUn **experimento conductual** es como hacer de científico/a de tu propia ansiedad: escribís qué creés que va a pasar, lo ponés a prueba en una situación real y después comparás con lo que pasó.\n\nEste recurso tiene dos partes: **planificar** el experimento ahora y **completar el resultado** después de hacerlo. Lo ideal es planificarlo y acordarlo con tu psicólogo/a antes de ponerlo en práctica." }, { "id": "seguridad", "type": "info", "title": "Antes de empezar", "content": "**Si estás en crisis o aparecen pensamientos de hacerte daño, pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos.\n\nElegí un experimento **desafiante pero manejable**. No hace falta empezar por lo más difícil: se avanza de a poco, con un plan acordado en sesión." }, { "id": "situacion", "type": "text", "prompt": "¿Qué situación social vas a usar para tu experimento? ¿Cuándo y dónde?", "placeholder": "Por ejemplo: hacer una pregunta en la reunión del miércoles" }, { "id": "prediccion", "type": "text", "prompt": "¿Qué temés que pase? Escribí tu predicción de forma concreta y observable.", "help": "Mejor algo que se pueda comprobar. En lugar de «va a salir mal», por ejemplo: «me voy a quedar en blanco, se van a reír y nadie va a responder mi pregunta».", "placeholder": "Creo que va a pasar…" }, { "id": "creencia_prediccion", "type": "scale", "prompt": "¿Cuánto creés, ahora, que tu predicción se va a cumplir?", "min": 0, "max": 100, "min_label": "Nada", "max_label": "Totalmente" }, { "id": "seguridad_info", "type": "info", "title": "Conductas de seguridad: soltar el salvavidas", "content": "Las **conductas de seguridad** son cosas que hacemos para que «no se note» la ansiedad o para evitar lo temido: ensayar cada frase en la cabeza, no hacer contacto visual, hablar poco, tener el celular en la mano, ponerse en un rincón.\n\nEl problema es doble:\n\n- Si todo sale bien, la mente piensa «me salvé **gracias** a eso», y el miedo no cambia.\n- A veces, además, empeoran las cosas: por ejemplo, ensayar en la cabeza hace que estés menos presente en la conversación.\n\nPor eso, en un experimento intentamos **soltar** una o más de esas conductas para comprobar qué pasa sin ellas." }, { "id": "conductas", "type": "checklist", "prompt": "¿Qué conductas de seguridad vas a intentar soltar en este experimento?", "options": [ "Ensayar mentalmente lo que voy a decir", "Evitar el contacto visual", "Hablar lo mínimo", "Mirar el celular para no interactuar", "Quedarme cerca de la salida o en un rincón", "Taparme la cara o esconder las manos", "Monitorear todo el tiempo cómo me veo" ], "min": 1, "max": 3 }, { "id": "observar", "type": "text", "prompt": "¿Qué vas a observar para saber si tu predicción se cumplió?", "help": "Pensá en señales concretas: ¿alguien se rió?, ¿me respondieron?, ¿la conversación siguió? Intentá mirar hacia afuera, no solo cómo te sentís por dentro.", "placeholder": "Voy a fijarme si…" }, { "id": "despues_info", "type": "info", "title": "Después del experimento", "content": "Los próximos pasos se completan **después** de hacer el experimento. Podés guardar este recurso y volver a abrirlo, o anotar el resultado en sesión.\n\nAlgunas cosas para tener en cuenta al mirar el resultado:\n\n- Es probable que sientas ansiedad durante el experimento. **Eso no es un fracaso**: el objetivo no es no sentir nervios, sino ver qué pasa en realidad.\n- Tratá de separar **lo que sentiste** de **lo que pasó**. «Sentí que me ponía rojo/a» no es lo mismo que «la gente reaccionó mal».\n- Si algo de lo que temías pasó, mirá también cómo lo manejaste y qué tan grave fue de verdad." }, { "id": "resultado", "type": "text", "prompt": "¿Qué pasó realmente? Describí los hechos, lo más concreto posible.", "placeholder": "Hice la pregunta, me trabé un poco al principio y…", "optional": true }, { "id": "creencia_final", "type": "scale", "prompt": "Después del experimento, ¿cuánto creés tu predicción original?", "min": 0, "max": 100, "min_label": "Nada", "max_label": "Totalmente", "optional": true }, { "id": "conclusion", "type": "text", "prompt": "¿Qué aprendiste? ¿Qué conclusión sacás para la próxima vez?", "placeholder": "Aprendí que…", "optional": true }, { "id": "cierre", "type": "reflect", "title": "Tu experimento", "template": "Situación: {{situacion}}. Mi predicción: {{prediccion}}. Conductas de seguridad a soltar: {{conductas}}. Voy a observar: {{observar}}. Qué pasó: {{resultado}}. Lo que aprendí: {{conclusion}}.", "content": "Un solo experimento rara vez cambia todo. La idea es repetirlos y ir subiendo la dificultad de a poco, junto con tu psicólogo/a." } ]$steps$::jsonb),
  ('cuadro-fobias-act-disposicion', 'Miedo: hacerle lugar para ir hacia lo que te importa', 'Desde ACT: la metáfora del pasajero en el colectivo, la disposición a sentir miedo al servicio de tus valores y un paso valioso para dar.', 'custom', 'act', 'todos', 'cuadros', 12, 345,
   $steps$[ { "id": "intro", "type": "info", "title": "¿Y si no hace falta esperar a no tener miedo?", "content": "Cuando algo nos da mucho miedo, es lógico querer que el miedo se vaya **antes** de hacer cosas. Pero a veces esa espera se hace larga, y mientras tanto la vida se achica: dejamos de ir, de hablar, de probar.\n\nLa **Terapia de Aceptación y Compromiso (ACT)** propone otra pregunta: no «¿cómo hago para no sentir miedo?», sino «**¿qué es lo que me importa y estoy dispuesto/a a sentir miedo para acercarme a eso?**».\n\nA eso se le llama **disposición** (en inglés, *willingness*): abrirle la puerta a la incomodidad, no porque te guste, sino porque te importa adónde vas." }, { "id": "seguridad", "type": "info", "title": "Antes de empezar", "content": "**Si estás en crisis o aparecen pensamientos de hacerte daño, pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos.\n\nDisposición no significa tirarte a lo más difícil de golpe ni aguantar a la fuerza. Los pasos los elegís vos, y conviene acordarlos con tu psicólogo/a." }, { "id": "valor", "type": "text", "prompt": "¿Qué te gustaría hacer o vivir si el miedo no decidiera por vos?", "help": "Pensá en lo que te importa: vínculos, estudiar, trabajar, viajar, disfrutar. Por ejemplo: «ir a los cumpleaños de mis amigos», «presentarme a un trabajo nuevo».", "placeholder": "Me gustaría…" }, { "id": "costo", "type": "text", "prompt": "¿Qué te viene costando evitar lo que temés? ¿Qué te perdiste?", "placeholder": "Por evitarlo, dejé de…" }, { "id": "colectivo", "type": "info", "title": "El pasajero en el colectivo", "content": "Imaginá que manejás un colectivo. Es **tu** colectivo, y el recorrido lo elegís vos: va hacia lo que te importa.\n\nEn el camino se suben pasajeros: el miedo, los pensamientos de «vas a hacer el ridículo», el corazón acelerado. Algunos son ruidosos y amenazantes. Te gritan: «¡doblá acá! ¡volvé a casa!».\n\nPodés hacerles caso para que se callen: doblás, volvés, y por un rato hay calma… pero terminás lejos de donde querías ir.\n\nO podés seguir manejando **con los pasajeros a bordo**. Siguen gritando, pero no tienen el volante. No hace falta echarlos ni convencerlos. Solo seguir el recorrido que elegiste." }, { "id": "pasajeros", "type": "list", "prompt": "¿Qué «pasajeros» se te suben cuando te acercás a lo que temés? (pensamientos, sensaciones, impulsos)", "help": "Por ejemplo: «se van a dar cuenta de que estoy nervioso/a», el corazón a mil, ganas de irme.", "count": 4, "min": 1 }, { "id": "quiz_disposicion", "type": "choice", "prompt": "En ACT, ¿qué significa estar dispuesto/a a sentir miedo?", "options": [ "Que me tiene que gustar sentir miedo", "Hacerle lugar al miedo mientras hago algo que me importa", "Aguantar apretando los dientes hasta que pase" ], "feedback": { "Que me tiene que gustar sentir miedo": "No hace falta que te guste. La disposición es hacerle lugar a algo incómodo, no desearlo.", "Hacerle lugar al miedo mientras hago algo que me importa": "Exacto. El miedo puede venir de pasajero; vos seguís manejando hacia donde elegiste.", "Aguantar apretando los dientes hasta que pase": "Es una confusión frecuente. Aguantar con tensión es otra forma de pelear con el miedo. La disposición es más abierta: notarlo, dejarlo estar y seguir." } }, { "id": "practica_lugar", "type": "timed_info", "title": "Hacerle lugar al miedo", "content": "Traé a la mente, con suavidad, la situación que te da miedo. No la más difícil: una intermedia.\n\n- Notá dónde aparece el miedo en el cuerpo. ¿Pecho, panza, garganta?\n- Respirá hacia esa zona, como si le hicieras espacio.\n- Ponele nombre: «acá está el miedo».\n- No intentes que se vaya. Solo dejalo estar, como un pasajero más.\n\nSi en algún momento se vuelve demasiado, abrí los ojos, mirá a tu alrededor y apoyá los pies en el piso.", "seconds": 90 }, { "id": "disposicion", "type": "scale", "prompt": "¿Qué tan dispuesto/a estás a sentir miedo si eso te acerca a lo que te importa?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Totalmente" }, { "id": "paso", "type": "text", "prompt": "Elegí un paso valioso, chico y concreto, que podrías dar esta semana con los pasajeros a bordo.", "help": "Que vaya en dirección a tu valor y sea posible. Por ejemplo: «quedarme 20 minutos en el cumpleaños del sábado», «mandar un mensaje para preguntar por el curso».", "placeholder": "Qué, cuándo y dónde…" }, { "id": "frase", "type": "text", "prompt": "¿Qué te vas a decir cuando los pasajeros empiecen a gritar?", "placeholder": "Por ejemplo: «ahí está el miedo; puede venir conmigo, yo sigo manejando»" }, { "id": "cierre", "type": "reflect", "title": "Tu recorrido", "template": "Lo que me importa: {{valor}}. Mis pasajeros: {{pasajeros}}. Mi paso valioso: {{paso}}. Me voy a decir: «{{frase}}».", "content": "El éxito no se mide por cuánto miedo sentiste, sino por si diste el paso que elegiste. Contá en sesión cómo te fue." } ]$steps$::jsonb),
  ('cuadro-tdah-dbt-emociones', 'TDAH: cuando la emoción llega rápido', 'Desde DBT: habilidades para la frustración que se dispara y la sensibilidad al rechazo: STOP, verificar los hechos y acción opuesta.', 'custom', 'dbt', 'todos', 'cuadros', 15, 346,
   $steps$[ { "id": "intro", "type": "info", "title": "Emociones a toda velocidad", "content": "Muchas personas con TDAH cuentan que las emociones les llegan **rápido y fuerte**: una frustración que pasa de cero a cien porque algo no sale, o un comentario que se siente como un rechazo enorme y queda dando vueltas horas.\n\nNo es exageración ni falta de carácter: las mismas funciones que ayudan a frenar un impulso también participan en frenar una reacción emocional.\n\nLa **Terapia Dialéctica Conductual (DBT)** tiene habilidades para esos momentos. Hoy vas a practicar tres:\n\n- **STOP**, para frenar antes de reaccionar.\n- **Verificar los hechos**, para ver si la emoción encaja con lo que pasó.\n- **Acción opuesta**, cuando la emoción empuja a algo que no te sirve." }, { "id": "seguridad", "type": "info", "title": "Antes de empezar", "content": "**Si estás en crisis o aparecen pensamientos de hacerte daño, pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos.\n\nSi la emoción es muy intensa ahora mismo, usá primero una herramienta de **Calmarme** y volvé a este ejercicio cuando estés más tranquilo/a." }, { "id": "situacion", "type": "text", "prompt": "Pensá en una situación reciente en que la emoción te desbordó rápido. ¿Qué pasó?", "placeholder": "Por ejemplo: mi pareja me dijo que me olvidé de algo y exploté" }, { "id": "emocion", "type": "checklist", "prompt": "¿Qué emociones aparecieron?", "options": [ "Frustración", "Enojo", "Vergüenza", "Tristeza", "Sentirme rechazado/a", "Ansiedad", "Culpa" ], "min": 1, "max": 4 }, { "id": "intensidad", "type": "scale", "prompt": "En ese momento, ¿qué tan intensa fue la emoción?", "min": 0, "max": 10, "min_label": "Leve", "max_label": "Al máximo" }, { "id": "stop_info", "type": "info", "title": "STOP: frenar antes de reaccionar", "content": "Cuando sentís que la emoción se dispara:\n\n- **S — Stop (pará):** quedate quieto/a un instante. No digas ni hagas nada todavía.\n- **T — Tomá distancia:** un paso atrás, literal o mental. Respirá. Si podés, salí unos minutos del lugar.\n- **O — Observá:** ¿qué pasa adentro tuyo (cuerpo, pensamientos, impulsos) y afuera (qué dijo o hizo la otra persona)?\n- **P — Proceder con atención:** elegí qué hacer pensando en lo que querés lograr, no en lo que pide la emoción.\n\nCon TDAH ayuda tener una **señal física** para el «Stop»: apretar las manos, apoyar los pies, tocar algo frío." }, { "id": "stop_senal", "type": "text", "prompt": "¿Qué señal física vas a usar para recordar el «Stop» en el momento?", "placeholder": "Por ejemplo: apretar el pulgar con el índice y soltar el aire" }, { "id": "stop_practica", "type": "timed_info", "title": "Practicá STOP ahora", "content": "Traé la situación a la mente, sin meterte del todo.\n\n- **Pará:** hacé tu señal física.\n- **Tomá distancia:** exhalá largo, dos o tres veces.\n- **Observá:** ¿qué sentís en el cuerpo? ¿qué impulso aparece? ¿qué está pasando realmente afuera?\n- **Procedé:** preguntate «¿qué haría ahora si quiero cuidar esta relación o esta tarea?».\n\nNo hace falta que la emoción desaparezca. Solo estás abriendo un espacio entre sentir y actuar.", "seconds": 60 }, { "id": "hechos_info", "type": "info", "title": "Verificar los hechos", "content": "La sensibilidad al rechazo hace que algunos gestos se lean enseguida como «no me quiere», «piensa que soy un desastre». Verificar los hechos ayuda a separar **lo que pasó** de **lo que interpreté**.\n\nPreguntas para hacerte:\n\n- ¿Qué pasó exactamente? ¿Qué dijo o hizo, palabra por palabra?\n- ¿Qué interpreté yo? ¿Hay otras explicaciones posibles?\n- ¿Estoy suponiendo una amenaza o un rechazo? ¿Qué tan probable es?\n- ¿La intensidad de mi emoción encaja con los hechos?\n\nA veces la emoción encaja y está bien sentirla. Otras veces, al mirar los hechos, baja sola." }, { "id": "hechos", "type": "text", "prompt": "En tu situación, ¿qué pasó exactamente y qué interpretaste vos?", "placeholder": "Lo que pasó: … / Lo que interpreté: …" }, { "id": "otra_explicacion", "type": "text", "prompt": "¿Qué otra explicación posible hay para lo que pasó?", "placeholder": "Tal vez…" }, { "id": "accion_opuesta", "type": "choice", "prompt": "Si la emoción no encaja con los hechos, ¿qué sería actuar de forma opuesta a su impulso?", "options": [ "Frustración que me empuja a abandonar: hacer un paso más chiquito y seguir", "Vergüenza que me empuja a esconderme: mantener el contacto con calma", "Enojo que me empuja a atacar: hablar con voz suave o tomarme un rato", "Sentir rechazo y aislarme: acercarme o preguntar qué quiso decir" ], "feedback": { "Frustración que me empuja a abandonar: hacer un paso más chiquito y seguir": "Muy útil con TDAH: achicar la tarea a algo de 2 o 5 minutos le quita fuerza a la frustración.", "Vergüenza que me empuja a esconderme: mantener el contacto con calma": "La acción opuesta a la vergüenza es no esconderse: postura erguida, mirada, seguir participando.", "Enojo que me empuja a atacar: hablar con voz suave o tomarme un rato": "Con el enojo, la acción opuesta es suavizar: alejarte un momento, bajar el tono, intentar entender a la otra persona.", "Sentir rechazo y aislarme: acercarme o preguntar qué quiso decir": "Preguntar con curiosidad («¿lo dijiste por…?») muchas veces desarma una interpretación de rechazo." } }, { "id": "plan", "type": "text", "prompt": "La próxima vez que pase algo parecido, ¿qué vas a hacer?", "placeholder": "Voy a hacer mi señal de Stop, y después…" }, { "id": "cierre", "type": "reflect", "title": "Tu plan", "template": "Situación: {{situacion}}. Emociones: {{emocion}}. Mi señal de Stop: {{stop_senal}}. Otra explicación posible: {{otra_explicacion}}. Acción opuesta que elijo: {{accion_opuesta}}. La próxima vez: {{plan}}.", "content": "Estas habilidades se aprenden con práctica, y al principio puede que te acuerdes de usarlas recién después. Eso también cuenta: revisar lo que pasó es parte del aprendizaje." } ]$steps$::jsonb),
  ('cuadro-tdah-tcc-postergacion', 'TDAH: salir de la postergación', 'Desde la TCC: detectá los pensamientos que sostienen la postergación, usá la regla de los 5 minutos, definí un primer paso y elegí una recompensa.', 'custom', 'tcc', 'todos', 'cuadros', 12, 347,
   $steps$[ { "id": "intro", "type": "info", "title": "Postergar no es ser vago/a", "content": "Postergar es muy común, y con TDAH suele ser más intenso: cuesta arrancar tareas aburridas, largas o poco claras, aunque sean importantes para vos.\n\nPostergar no es pereza. Muchas veces es una forma de **evitar una emoción incómoda**: aburrimiento, miedo a hacerlo mal, sensación de no saber por dónde empezar. Al postergar, el malestar baja un rato… y después vuelve más fuerte, con culpa incluida.\n\nEn este ejercicio de **TCC** vas a:\n\n- Detectar los **pensamientos** que sostienen la postergación.\n- Probar la **regla de los 5 minutos**.\n- Definir un **primer paso** concreto y una **recompensa**." }, { "id": "seguridad", "type": "info", "title": "Antes de empezar", "content": "**Si estás en crisis o aparecen pensamientos de hacerte daño, pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos." }, { "id": "tarea", "type": "text", "prompt": "¿Qué tarea venís postergando y te gustaría destrabar?", "placeholder": "Por ejemplo: hacer el trámite del banco, empezar el trabajo práctico" }, { "id": "pensamientos", "type": "checklist", "prompt": "¿Cuáles de estos pensamientos aparecen cuando pensás en esa tarea?", "options": [ "Lo hago cuando tenga ganas", "Tiene que salir perfecto", "Trabajo mejor bajo presión", "Es demasiado, no sé por dónde empezar", "Primero tengo que ordenar todo lo demás", "Ya es tarde para hacerlo bien", "Mañana voy a tener más energía" ], "min": 1, "max": 7 }, { "id": "pensamientos_info", "type": "info", "title": "Revisar esos pensamientos", "content": "Estos pensamientos suenan razonables, pero suelen mantener la postergación:\n\n- **«Lo hago cuando tenga ganas»:** las ganas muchas veces llegan **después** de empezar, no antes. Esperar la motivación puede ser esperar mucho.\n- **«Tiene que salir perfecto»:** si la vara está altísima, empezar da miedo. Un borrador imperfecto es mejor que una tarea perfecta que no existe.\n- **«Trabajo mejor bajo presión»:** a veces la urgencia ayuda a arrancar, pero también suma estrés, errores y noches sin dormir.\n- **«Es demasiado»:** la tarea entera abruma; un paso chico, no.\n\nUna pregunta útil: «¿qué le diría a un amigo/a que piensa esto?»." }, { "id": "alternativo", "type": "text", "prompt": "Elegí el pensamiento que más te frena y escribí una respuesta más útil.", "placeholder": "Por ejemplo: «no necesito ganas para empezar, solo 5 minutos; las ganas pueden venir después»" }, { "id": "primer_paso", "type": "text", "prompt": "¿Cuál es el primer paso más chiquito y concreto de esa tarea? Algo que se pueda empezar ya.", "help": "Tan chico que dé un poco de vergüenza. «Hacer el trabajo» es mucho; «abrir el archivo y escribir el título» es un primer paso.", "placeholder": "Por ejemplo: buscar el formulario en la página del banco" }, { "id": "cinco_info", "type": "info", "title": "La regla de los 5 minutos", "content": "La idea es simple: te comprometés a trabajar en la tarea **solo 5 minutos**. Cuando pasan, podés parar sin culpa.\n\n¿Por qué funciona? Porque arrancar es lo más difícil. Cinco minutos se sienten posibles, y muchas veces, una vez que empezaste, seguir cuesta menos. Si parás a los 5 minutos, igual avanzaste.\n\nAyuda mucho usar un **temporizador** visible y preparar el entorno antes: celular lejos, solo lo necesario a mano." }, { "id": "cinco_practica", "type": "timed_info", "title": "Probalo ahora (o preparalo)", "content": "Si la tarea se puede empezar ahora, hacé tu primer paso durante estos minutos. Cuando suene, decidí si seguís o parás.\n\nSi no se puede ahora, usá este tiempo para **preparar el terreno**:\n\n- Dejá a mano lo que vas a necesitar.\n- Anotá el primer paso en un papel visible.\n- Poné una alarma para el momento en que vas a empezar.", "seconds": 180 }, { "id": "cuando", "type": "text", "prompt": "Si no la empezaste ahora, ¿cuándo y dónde vas a hacer tus 5 minutos?", "placeholder": "Por ejemplo: mañana a las 10, en el escritorio, con el celular en otra habitación", "optional": true }, { "id": "recompensa", "type": "text", "prompt": "¿Qué recompensa chica te vas a dar después de hacerlo?", "help": "Con TDAH, las recompensas inmediatas ayudan más que las lejanas. Por ejemplo: un mate, un capítulo de una serie, un rato de música, contarle a alguien que lo hiciste.", "placeholder": "Después me voy a…" }, { "id": "como_fue", "type": "choice", "prompt": "Si ya probaste los 5 minutos, ¿qué pasó?", "options": [ "Seguí más tiempo", "Hice los 5 minutos y paré", "Me costó arrancar", "Todavía no lo probé" ], "feedback": { "Seguí más tiempo": "¡Muy bien! Notá esto: las ganas llegaron después de empezar. Es un buen dato para la próxima vez.", "Hice los 5 minutos y paré": "Eso es cumplir el plan. Cinco minutos de avance son mucho más que cero. Date tu recompensa.", "Me costó arrancar": "Es frecuente. Probá achicar todavía más el primer paso, o hacerlo acompañado/a (alguien al lado, aunque haga otra cosa).", "Todavía no lo probé": "Está bien. Lo importante es que tengas el primer paso definido y un momento elegido para hacerlo." } }, { "id": "cierre", "type": "reflect", "title": "Tu plan contra la postergación", "template": "Tarea: {{tarea}}. Pensamientos que me frenan: {{pensamientos}}. Me voy a decir: «{{alternativo}}». Primer paso: {{primer_paso}}. Cuándo: {{cuando}}. Recompensa: {{recompensa}}.", "content": "Si un día no sale, no es una prueba de que «no tenés remedio». Es información para ajustar el plan: un paso más chico, otro horario, otra recompensa. Podés revisarlo en sesión." } ]$steps$::jsonb),
  ('cuadro-alimentacion-dbt-impulsos', 'Comida: surfear el impulso', 'Desde DBT: cómo atravesar el impulso de atracón o de compensar sin actuarlo, con surfear la ola, distracción y autocalmarte.', 'custom', 'dbt', 'todos', 'cuadros', 15, 348,
   $steps$[ { "id": "intro", "type": "info", "title": "El impulso es una ola", "content": "A veces aparece un impulso muy fuerte: comer mucho y rápido, o hacer algo para «compensar» lo que comiste. En ese momento parece que no hay otra salida y que el malestar no va a parar nunca.\n\nPero los impulsos funcionan como **olas**: suben, llegan a un pico y, si no les damos de comer, **bajan solos**. Lo que mantiene el problema es que actuar el impulso alivia por un rato, y el cerebro aprende que esa es la única forma de calmarse.\n\nEn este ejercicio de **DBT** vas a practicar:\n\n- **Surfear el impulso**: observarlo sin actuarlo.\n- **Distracción** y **autocalmarte**, para atravesar el pico.\n\nEstas habilidades funcionan mejor como parte de un **tratamiento en equipo** (psicología, medicina y nutrición)." }, { "id": "seguridad", "type": "info", "title": "Cuándo pedir ayuda ya", "content": "**Si estás en crisis o aparecen pensamientos de hacerte daño, pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos.\n\nConsultá **con urgencia** a un médico o andá a la guardia si tenés **desmayos o mareos fuertes**, **palpitaciones** o latidos irregulares, dolor en el pecho, confusión, mucha debilidad o vómitos que no paran. Las conductas compensatorias pueden afectar el cuerpo aunque por fuera no se note." }, { "id": "momentos", "type": "checklist", "prompt": "¿En qué momentos suele aparecer el impulso? Marcá los que reconozcas.", "options": [ "Después de pasar mucho tiempo sin comer", "Cuando estoy solo/a en casa", "Después de una discusión o un mal momento", "Cuando estoy aburrido/a o cansado/a", "De noche", "Después de mirarme o compararme", "Después de comer algo que considero «prohibido»" ], "min": 1, "max": 7 }, { "id": "senales", "type": "text", "prompt": "¿Cómo te das cuenta de que el impulso está empezando? ¿Qué sentís o pensás?", "placeholder": "Por ejemplo: ansiedad en el pecho, pensamiento de «ya fue, total…», ir a la cocina sin pensar" }, { "id": "surfear_info", "type": "info", "title": "Cómo surfear el impulso", "content": "Cuando aparece el impulso, en lugar de pelear con él o seguirlo, lo **observás con curiosidad**, como un surfista que se sube a la ola:\n\n- **Notá** dónde lo sentís en el cuerpo: panza, pecho, boca, manos.\n- **Ponele un número** del 0 al 10 a su intensidad.\n- **Respirá** despacio, con la exhalación más larga.\n- **Describilo** sin juzgarlo: «tengo un impulso fuerte de comer, está en 8».\n- **Seguí observando** cómo cambia. Sube, se mantiene, baja.\n\nNo tenés que hacer que el impulso desaparezca. Solo dejar que pase **sin actuarlo**. Cada vez que lo atravesás, el cerebro aprende que podés." }, { "id": "surfear_practica", "type": "timed_info", "title": "Practicá surfear la ola", "content": "Si ahora no tenés un impulso, recordá uno reciente, con suavidad.\n\n- Apoyá los pies en el piso y notá tu respiración.\n- Buscá en el cuerpo dónde está el impulso. ¿Qué forma tiene? ¿Es calor, presión, inquietud?\n- Ponele un número.\n- Imaginá que es una ola: notá cómo sube… y acompañala con la respiración.\n- Cada tanto, volvé a ponerle número. ¿Cambió algo?\n\nSi en algún momento se vuelve demasiado intenso, abrí los ojos, mirá cinco cosas a tu alrededor y pasá a la distracción.", "seconds": 120 }, { "id": "intensidad", "type": "scale", "prompt": "Al terminar la práctica, ¿qué tan intenso es el impulso (o el recuerdo del impulso)?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Muy intenso", "maps_to": "emotion_after" }, { "id": "distraccion_info", "type": "info", "title": "Distracción y autocalmarte", "content": "Mientras la ola pasa, ayuda **cambiar de escenario** un rato. No es «tapar» lo que sentís: es darle tiempo al impulso para que baje.\n\n**Distracción:** salir de la cocina o del lugar donde aparece el impulso, llamar o escribirle a alguien, ordenar algo, una serie, un juego, salir a la vereda.\n\n**Autocalmarte con los sentidos:** algo tibio en las manos, una ducha, música tranquila, un aroma que te guste, una manta, mirar algo lindo.\n\nUna regla útil: **esperar al menos 20 minutos** haciendo otra cosa antes de decidir. Muchas veces el impulso baja en ese tiempo." }, { "id": "plan_distraccion", "type": "list", "prompt": "Armá tu lista: ¿qué cosas de distracción o para calmarte podrías hacer cuando aparezca el impulso?", "help": "Que sean posibles en tu casa, a cualquier hora, y lejos de la cocina si se puede.", "count": 5, "min": 3 }, { "id": "persona", "type": "text", "prompt": "¿A quién podrías escribirle o llamar en un momento así, aunque no le cuentes todo?", "placeholder": "Por ejemplo: mi hermana, una amiga", "optional": true }, { "id": "si_pasa", "type": "choice", "prompt": "Si a pesar de todo actuás el impulso, ¿qué ayuda más después?", "options": [ "Saltear la próxima comida para compensar", "Volver a comer de forma regular en la próxima comida", "Decirme que no sirvo para esto y abandonar" ], "feedback": { "Saltear la próxima comida para compensar": "Es lo que el cuerpo y la cabeza suelen pedir, pero saltear comidas alimenta el ciclo: más hambre, más impulso. Lo que ayuda es volver al plan de comidas regulares.", "Volver a comer de forma regular en la próxima comida": "Exacto. Volver a tu plan de comidas regulares corta el ciclo. Y anotar qué pasó (sin juzgarte) es información valiosa para la sesión.", "Decirme que no sirvo para esto y abandonar": "Los tropiezos son parte de cualquier proceso. La autocrítica dura suele aumentar el malestar y, con él, el impulso. Tratate como tratarías a alguien que querés." } }, { "id": "cierre", "type": "reflect", "title": "Tu plan para la próxima ola", "template": "Momentos de riesgo: {{momentos}}. Cómo me doy cuenta: {{senales}}. Mi lista para atravesar el pico: {{plan_distraccion}}. Puedo contactar a: {{persona}}.", "content": "Guardá esta lista en un lugar visible o en el celular. Contá en sesión cómo te fue: lo que funcionó y lo que no es información para ajustar el plan con tu equipo de tratamiento." } ]$steps$::jsonb),
  ('cuadro-alimentacion-tcc-imagen', 'Imagen corporal: mirar el cuerpo con otros ojos', 'Desde la TCC: reconocé el chequeo y la evitación del cuerpo, las comparaciones y el efecto de las redes, y probá una mirada funcional del cuerpo.', 'custom', 'tcc', 'todos', 'cuadros', 15, 349,
   $steps$[ { "id": "intro", "type": "info", "title": "Cuando el cuerpo ocupa demasiado lugar", "content": "Para muchas personas, cómo se ven ocupa un lugar enorme: en lo que piensan, en cómo se sienten con ellas mismas y en lo que hacen o dejan de hacer.\n\nLa **imagen corporal** no es solo cómo es tu cuerpo: es cómo lo **percibís**, qué **pensás** y **sentís** sobre él y qué **hacés** a partir de eso. Y esa imagen se puede trabajar.\n\nEn este ejercicio de **TCC** vas a mirar tres cosas que suelen mantener el malestar:\n\n- El **chequeo** del cuerpo.\n- La **evitación** del cuerpo.\n- Las **comparaciones**, incluidas las de las **redes sociales**.\n\nY vas a probar una forma distinta de mirarlo: por lo que **hace**, no solo por cómo se ve." }, { "id": "seguridad", "type": "info", "title": "Antes de empezar", "content": "**Si estás en crisis o aparecen pensamientos de hacerte daño, pedí ayuda ya:** a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos.\n\nSi tenés **desmayos, mareos fuertes, palpitaciones** o mucha debilidad, consultá con urgencia a un médico. Este ejercicio funciona mejor dentro de un tratamiento acompañado por tu equipo." }, { "id": "malestar", "type": "scale", "prompt": "Hoy, ¿cuánto malestar te genera pensar en tu cuerpo?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Muchísimo", "maps_to": "emotion_before" }, { "id": "chequeo_info", "type": "info", "title": "Chequear y evitar: dos caras de lo mismo", "content": "**Chequear** es revisar el cuerpo una y otra vez: mirarse en cada espejo o vidriera, pellizcarse, probarse la misma ropa para ver «cómo queda», pesarse seguido, sacarse fotos para controlar.\n\nEl chequeo parece dar tranquilidad, pero tiene trampa: **cuanto más mirás algo buscando defectos, más defectos encontrás**. La atención agranda lo que mira.\n\n**Evitar** es lo contrario: no mirarse nunca, tapar el cuerpo con ropa muy holgada, no ir a la playa o a la pileta, no dejar que te saquen fotos.\n\nLa evitación alivia un rato, pero mantiene el miedo y achica la vida. Muchas personas alternan entre las dos." }, { "id": "conductas", "type": "checklist", "prompt": "¿Cuáles de estas conductas reconocés en vos? Marcá las que quieras.", "options": [ "Mirarme mucho en espejos o vidrieras", "Pellizcarme o tocar partes del cuerpo para controlarlas", "Probarme ropa para ver si me queda igual", "Sacarme fotos para revisar cómo me veo", "Evitar espejos", "Usar ropa para taparme", "Evitar fotos, playa, pileta o ciertas salidas", "Compararme con otras personas" ], "min": 1, "max": 8 }, { "id": "conducta_reducir", "type": "text", "prompt": "Elegí una conducta de chequeo o evitación para empezar a reducir. ¿Qué podrías hacer distinto?", "help": "Pasos chicos. Por ejemplo: «usar el espejo solo para peinarme, sin revisar el cuerpo» o «ir a la pileta con mi amiga aunque me dé vergüenza».", "placeholder": "Voy a…" }, { "id": "comparaciones_info", "type": "info", "title": "Comparaciones y redes sociales", "content": "Cuando nos comparamos, solemos hacerlo de forma **injusta**: elegimos a la persona que más se acerca al ideal, la miramos en su mejor momento y la comparamos con la parte de nosotros que menos nos gusta.\n\nEn las **redes** esto se multiplica: las imágenes están elegidas, editadas y filtradas, y el algoritmo muestra más de lo que más mirás.\n\nAlgunas preguntas útiles:\n\n- ¿Con quién me comparo y en qué situación?\n- ¿Me comparo con la persona entera o solo con una parte de su cuerpo?\n- ¿Cómo me siento después de mirar ciertas cuentas?\n\nNo se trata de dejar las redes, sino de elegir qué querés ver." }, { "id": "redes", "type": "checklist", "prompt": "¿Qué cambios podrías probar con tus redes esta semana?", "options": [ "Silenciar o dejar de seguir cuentas que me hacen sentir mal con mi cuerpo", "Seguir cuentas sobre otros intereses (arte, deporte, humor, naturaleza)", "Seguir cuentas con cuerpos diversos y reales", "Limitar el tiempo en las apps que más me afectan", "No mirar redes antes de dormir o al despertarme" ], "min": 1, "max": 5 }, { "id": "funcional_info", "type": "timed_info", "title": "Tu cuerpo, por lo que hace", "content": "Tomate un par de minutos para pensar en tu cuerpo de otra forma: no por cómo se ve, sino por lo que **te permite hacer**.\n\n- Tus piernas, que te llevan a lugares.\n- Tus brazos y manos, que abrazan, cocinan, escriben, saludan.\n- Tus sentidos: lo que ves, escuchás, saboreás.\n- Tu respiración y tu corazón, que trabajan todo el día sin que se lo pidas.\n- Tu cuerpo en momentos lindos: bailando, riéndote, descansando.\n\nNo hace falta que te guste todo de tu cuerpo. Solo probá mirarlo, por un rato, desde lo que hace por vos.", "seconds": 120 }, { "id": "funcional", "type": "list", "prompt": "Escribí tres cosas que tu cuerpo te permite hacer y que valorás.", "count": 3, "min": 3 }, { "id": "malestar_despues", "type": "scale", "prompt": "Ahora, ¿cuánto malestar te genera pensar en tu cuerpo?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Muchísimo", "maps_to": "emotion_after" }, { "id": "cierre", "type": "reflect", "title": "Lo que te llevás", "template": "Conductas que reconozco: {{conductas}}. Voy a empezar por: {{conducta_reducir}}. Con las redes voy a probar: {{redes}}. Mi cuerpo me permite: {{funcional}}.", "content": "Cambiar la relación con el cuerpo lleva tiempo y suele tener idas y vueltas. Si este ejercicio te removió cosas difíciles, traelas a la próxima sesión." } ]$steps$::jsonb),
  ('cuadro-autoestima-tcc-creencias', 'Revisar una creencia de fondo sobre mí', 'Identificá una creencia nuclear como «no valgo», registrá evidencias a favor y en contra, y armá una creencia alternativa más justa.', 'custom', 'tcc', 'todos', 'cuadros', 14, 350,
   $steps$[ { "id": "intro", "type": "info", "title": "Una creencia, una semana", "content": "Las **creencias nucleares** son ideas de fondo sobre vos, como «no valgo» o «soy insuficiente». Funcionan como anteojos: te hacen ver lo que las confirma y pasar por alto lo que las contradice.\n\nEn este recurso vas a elegir **una sola creencia** y tratarla como lo que es: una **hipótesis aprendida**, no una verdad. Vas a juntar evidencia de los dos lados, como haría un buen investigador, y armar una idea más equilibrada.\n\nNo se trata de pensar «positivo» a la fuerza. Se trata de mirarte con **todos los datos**, no solo con los que la creencia elige." }, { "id": "seguridad", "type": "info", "title": "Antes de empezar", "content": "Si mientras hacés este recurso aparecen pensamientos de hacerte daño, de que no valés la pena vivir, o sentís que estás en crisis, **dejá el ejercicio para otro momento y pedí ayuda ya**: a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos.\n\nNo tenés que atravesarlo solo ni sola. Contáselo también a tu psicólogo." }, { "id": "creencias_tipicas", "type": "checklist", "prompt": "¿Cuáles de estas frases se parecen a lo que sentís de vos en los peores momentos?", "options": [ "«No valgo»", "«Soy insuficiente»", "«No soy querible»", "«Soy un fracaso»", "«Soy menos que los demás»", "«Soy una carga para otros»", "Otra parecida" ], "min": 1 }, { "id": "creencia", "type": "text", "prompt": "Elegí una sola y escribila con tus palabras. Empezá con «Soy…» o «No soy…».", "placeholder": "Soy…" }, { "id": "credibilidad_antes", "type": "scale", "prompt": "Ahora mismo, ¿cuánto te creés esa idea sobre vos?", "min": 0, "max": 100, "min_label": "0 %: nada", "max_label": "100 %: totalmente" }, { "id": "como_registrar", "type": "info", "title": "Cómo se junta evidencia", "content": "Durante una semana, tomate **unos minutos por día** para anotar dos columnas:\n\n- **A favor:** situaciones que parecen confirmar la creencia.\n- **En contra:** situaciones que no encajan con ella, aunque sean chicas.\n\nAlgunas reglas que ayudan:\n\n- Anotá **hechos**, no conclusiones. «Me olvidé de llamar a mi hermana» es un hecho; «soy un desastre» es una conclusión.\n- La columna «en contra» suele costar más: los anteojos la esconden. Preguntate **qué diría alguien que te quiere**.\n- Cuentan las cosas cotidianas: cumplir algo, ayudar a alguien, animarte a algo difícil, recibir un gesto de cariño." }, { "id": "a_favor", "type": "list", "prompt": "Empezá hoy: ¿qué hechos de estos días parecen confirmar la creencia?", "count": 3, "min": 1 }, { "id": "hecho_o_conclusion", "type": "choice", "prompt": "Te equivocaste en algo del trabajo o del estudio. ¿Qué frase describe lo que pasó con más justicia?", "options": [ "«Soy un incompetente»", "«Cometí un error en esta tarea»", "«Nunca hago nada bien»" ], "feedback": { "«Soy un incompetente»": "**Esa es una conclusión sobre toda tu persona a partir de un hecho.** Fijate si alguna de tus evidencias «a favor» tiene esta forma: muchas veces son interpretaciones disfrazadas de hechos.", "«Cometí un error en esta tarea»": "**Exacto.** Describe lo que pasó sin convertirlo en un juicio sobre quién sos. Revisá tu lista «a favor» con este criterio.", "«Nunca hago nada bien»": "**El «nunca» borra todas las veces que sí salió bien.** Es una de las formas en que la creencia se defiende. Revisá tu lista «a favor» buscando palabras como «siempre», «nunca» o «todo»." } }, { "id": "en_contra", "type": "list", "prompt": "Ahora lo difícil: ¿qué hechos no encajan con esa creencia? Logros, cualidades, gestos que recibiste.", "help": "Si te cuesta, pensá en lo que diría alguien que te conoce bien y te quiere. También valen cosas de otras épocas de tu vida.", "count": 5, "min": 2 }, { "id": "alternativa_info", "type": "info", "title": "Una creencia más equilibrada", "content": "Con las dos columnas a la vista, la idea es escribir una **creencia alternativa**: una frase que tome en cuenta **toda** la evidencia, también tus límites.\n\nNo tiene que ser perfecta ni sonar a frase de póster. Tiene que ser **creíble**. Por ejemplo:\n\n- En lugar de «no valgo»: «Tengo cualidades y también cosas que me cuestan, como cualquier persona. Mi valor no depende de no equivocarme».\n- En lugar de «soy insuficiente»: «A veces no llego a todo, y eso no borra lo que sí hago»." }, { "id": "alternativa", "type": "text", "prompt": "Escribí tu creencia alternativa, equilibrada y creíble para vos.", "placeholder": "Soy una persona que…" }, { "id": "credibilidad_alternativa", "type": "scale", "prompt": "¿Cuánto te creés hoy la creencia alternativa? Está bien si es poco.", "min": 0, "max": 100, "min_label": "0 %: nada", "max_label": "100 %: totalmente" }, { "id": "credibilidad_despues", "type": "scale", "prompt": "Y después de mirar la evidencia, ¿cuánto te creés ahora la creencia original?", "min": 0, "max": 100, "min_label": "0 %: nada", "max_label": "100 %: totalmente" }, { "id": "cierre", "type": "reflect", "title": "Tu registro de esta semana", "template": "La creencia que estoy revisando es: «{{creencia}}». Hechos que parecían confirmarla: {{a_favor}}. Hechos que no encajan: {{en_contra}}. Una forma más justa de verlo: «{{alternativa}}».", "content": "**Para esta semana:** volvé cada día a sumar evidencias, sobre todo en la columna «en contra». Al final de la semana puntuá de nuevo cuánto te creés cada idea.\n\nLas creencias de fondo cambian **de a poco**, no de un día para otro: es normal que los porcentajes se muevan apenas. Traé el registro a tu próxima sesión." } ]$steps$::jsonb),
  ('cuadro-autoestima-act-yo', 'Vos no sos lo que tu mente dice de vos', 'El yo como contexto (ACT): mirá tus pensamientos sobre vos desde el lugar del observador y hacé algo valioso con la voz crítica a bordo.', 'custom', 'act', 'todos', 'cuadros', 12, 351,
   $steps$[ { "id": "intro", "type": "info", "title": "El que piensa y lo pensado", "content": "Tu mente produce juicios sobre vos todo el día: «sos lento», «no das la talla», «a nadie le importa lo que decís». Muchas veces esos juicios se sienten como **la verdad sobre quién sos**.\n\nEn ACT no se intenta ganarle la discusión a esa voz. Se propone algo distinto: notar que **hay una parte tuya que puede observar** esos pensamientos. Esa parte estuvo en todas tus edades, en tus días buenos y en los malos.\n\nLos pensamientos sobre vos cambian. **El lugar desde donde los notás, no.** A eso se le llama el «yo como contexto»." }, { "id": "seguridad", "type": "info", "title": "Antes de empezar", "content": "Si mientras hacés este recurso aparecen pensamientos de hacerte daño, de que no valés la pena vivir, o sentís que estás en crisis, **dejá el ejercicio para otro momento y pedí ayuda ya**: a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos.\n\nNo tenés que atravesarlo solo ni sola. Contáselo también a tu psicólogo." }, { "id": "voz_critica", "type": "text", "prompt": "¿Qué frase te dice la voz crítica sobre vos con más frecuencia?", "placeholder": "Me dice que…" }, { "id": "enganche_antes", "type": "scale", "prompt": "Cuando aparece esa frase, ¿cuánto te atrapa? ¿Cuánto te la creés y te arrastra?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Por completo" }, { "id": "cielo", "type": "info", "title": "El cielo y el clima", "content": "Imaginá que **vos sos el cielo** y que tus pensamientos, emociones y sensaciones son **el clima**.\n\nA veces hay sol, a veces nubes, a veces una tormenta fuerte. Pero ninguna tormenta, por más intensa que sea, **daña al cielo**. El cielo le hace lugar, la contiene, y sigue ahí cuando pasa.\n\nLa voz crítica es parte del clima. Puede ser una tormenta que dure días. Y aun así, **vos sos el espacio donde esa tormenta ocurre**, no la tormenta.\n\nDesde ese lugar no hace falta que el clima mejore para que puedas seguir viviendo." }, { "id": "metafora", "type": "choice", "prompt": "En esta metáfora, ¿qué lugar ocupás vos?", "options": [ "Las nubes de tormenta", "El cielo que las contiene", "El sol que tiene que ganarles" ], "feedback": { "Las nubes de tormenta": "**Así se siente cuando estamos enganchados:** como si fuéramos la tormenta. Pero las nubes vienen y van. Vos sos el cielo donde aparecen.", "El cielo que las contiene": "**Exacto.** Los pensamientos sobre vos son clima: cambian. Vos sos el espacio que los contiene, también cuando la tormenta es fuerte.", "El sol que tiene que ganarles": "**Es una idea muy común: que hay que pelear y vencer a los pensamientos negativos.** En ACT se propone otra cosa: no necesitás ganarle a la tormenta, podés hacerle lugar." } }, { "id": "observador", "type": "timed_info", "title": "Práctica del observador", "seconds": 120, "content": "Sentate cómodo o cómoda y, si querés, cerrá los ojos.\n\nNotá tu respiración, sin cambiarla. Notá el apoyo del cuerpo en la silla.\n\nAhora notá los pensamientos que aparezcan, como nubes que cruzan. Si aparece la voz crítica, nombrala: «ahí está el pensamiento de que…».\n\nY fijate en esto: **hay alguien que está notando**. Los pensamientos pasan; ese que nota se queda.\n\nRecordá un momento de cuando eras chico o chica. Ese mismo observador estaba ahí. Es el mismo que está ahora.\n\nCuando suene el aviso, volvé despacio al lugar donde estás." }, { "id": "lo_que_notaste", "type": "checklist", "prompt": "¿Qué notaste durante la práctica?", "options": [ "Pensamientos sobre mí", "Sensaciones en el cuerpo", "Ganas de cortar la práctica", "Un poco de distancia de la voz crítica", "Algo de calma", "Inquietud o incomodidad", "Nada en particular" ], "min": 1 }, { "id": "enganche_despues", "type": "scale", "prompt": "Pensando ahora en la frase crítica, ¿cuánto te atrapa en este momento?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Por completo" }, { "id": "accion_info", "type": "info", "title": "La voz puede venir de pasajera", "content": "Muchas personas esperan a que la voz crítica se calle para animarse: «cuando me sienta más seguro, me anoto», «cuando me crea capaz, lo digo».\n\nDesde ACT, la propuesta es al revés: **elegir una acción que te importe y hacerla con la voz a bordo**. La voz puede ir de pasajera; lo que no hace falta es dejarle el volante.\n\nNo tiene que ser algo grande. Alcanza con un paso chico, concreto y posible esta semana." }, { "id": "importa", "type": "text", "prompt": "¿Qué te importa y venís postergando porque la voz dice que no vas a estar a la altura?", "placeholder": "Me importa…" }, { "id": "accion", "type": "text", "prompt": "¿Qué paso chico y concreto vas a dar esta semana? ¿Cuándo?", "placeholder": "El jueves voy a…" }, { "id": "frase_observador", "type": "text", "prompt": "Cuando aparezca la voz, ¿qué te vas a decir? Ej.: «Ahí está la tormenta de siempre; soy el cielo y sigo».", "placeholder": "Me voy a decir…" }, { "id": "cierre", "type": "reflect", "title": "Tu plan", "template": "La voz crítica suele decirme: «{{voz_critica}}». Eso es clima, no es quién soy. Me importa {{importa}}, así que esta semana voy a {{accion}}. Cuando la voz aparezca, me voy a decir: «{{frase_observador}}».", "content": "Si la voz aparece fuerte mientras das el paso, **eso no significa que lo estés haciendo mal**: significa que estás haciendo algo que te importa. Podés repetir la práctica del observador cuando quieras y contar en sesión cómo te fue." } ]$steps$::jsonb),
  ('cuadro-pareja-dbt-pedir', 'Pedirle algo a mi pareja cuidando el vínculo', 'Habilidades DBT para la pareja: DEAR MAN para pedir con claridad, GIVE para cuidar la relación y tres niveles simples de validación.', 'custom', 'dbt', 'todos', 'cuadros', 14, 352,
   $steps$[ { "id": "intro", "type": "info", "title": "Pedir y cuidar a la vez", "content": "En pareja, muchas veces sentimos que hay que elegir: **o pido lo que necesito, o cuido la relación**. Entonces nos callamos hasta explotar, o pedimos de una manera que termina en pelea.\n\nDBT propone dos habilidades que se usan juntas:\n\n- **DEAR MAN**, para pedir algo con claridad.\n- **GIVE**, para cuidar el vínculo mientras hablan.\n\nNinguna garantiza que el otro diga que sí. Lo que sí hacen es **aumentar las chances** de que la conversación sea escuchada, y ayudarte a quedar bien con vos por cómo la llevaste." }, { "id": "seguridad", "type": "info", "title": "Primero, tu seguridad", "content": "**Si en tu relación hay violencia** (golpes, empujones, amenazas, insultos constantes, control de tu celular, tu plata o tus salidas) o sentís miedo de la reacción de tu pareja, **la prioridad es tu seguridad, no la técnica.** Estas habilidades sirven entre dos personas que pueden hablar sin peligro; no son para negociar con la violencia.\n\nSi estás en riesgo o en crisis, pedí ayuda ya: a emergencias, a una línea de ayuda o en la guardia del hospital más cercano. En la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos.\n\nTambién podés hablarlo con tu psicólogo para armar un plan de seguridad." }, { "id": "es_seguro", "type": "choice", "prompt": "¿Sentís que podés hablar de esto con tu pareja sin peligro?", "options": [ "Sí, puedo hablar tranquilo o tranquila", "No estoy seguro o segura", "No, tengo miedo de su reacción" ], "feedback": { "Sí, puedo hablar tranquilo o tranquila": "**Bien.** Seguí con el recurso para preparar tu pedido.", "No estoy seguro o segura": "**Esa duda merece atención.** Podés seguir para ordenar tus ideas, pero antes de tener la conversación hablalo con tu psicólogo o con alguien de confianza.", "No, tengo miedo de su reacción": "**Gracias por decirlo.** Si sentís miedo, la prioridad no es esta conversación sino tu seguridad. Hablalo con tu psicólogo y, si estás en riesgo, pedí ayuda ya desde el recuadro de ayuda urgente en **Calmarme**." } }, { "id": "dearman_info", "type": "info", "title": "DEAR MAN", "content": "Cada letra es un paso (las siglas vienen del inglés):\n\n- **D: Describir** la situación con hechos, sin juicios.\n- **E: Expresar** lo que sentís o pensás, en primera persona.\n- **A: Afirmar** tu pedido: decir claramente qué querés.\n- **R: Reforzar**: contar qué de bueno traería para los dos.\n\nY mientras hablás:\n\n- **M: Mantener el foco**. Si la charla se desvía, volvé con calma a tu pedido («disco rayado»).\n- **A: Aparentar seguridad**: tono firme, mirada tranquila, aunque estés nervioso o nerviosa.\n- **N: Negociar**: estar dispuesto o dispuesta a buscar una alternativa." }, { "id": "describir", "type": "text", "prompt": "D: Describí la situación solo con hechos, como la contaría una cámara.", "placeholder": "Las últimas tres noches cenamos con el celular en la mesa…" }, { "id": "expresar", "type": "text", "prompt": "E: Expresá qué sentís o pensás sobre eso. Empezá con «Me siento…» o «Me pasa que…».", "placeholder": "Me siento…" }, { "id": "afirmar", "type": "text", "prompt": "A: Pedí de forma clara y concreta. Empezá con «Me gustaría que…».", "placeholder": "Me gustaría que…" }, { "id": "reforzar", "type": "text", "prompt": "R: ¿Qué de bueno traería para los dos que esto se dé?", "placeholder": "Creo que nos ayudaría a…" }, { "id": "negociar", "type": "text", "prompt": "N: Si no puede o no quiere exactamente eso, ¿qué alternativa te parecería aceptable?", "placeholder": "Podríamos probar…", "optional": true }, { "id": "give_info", "type": "info", "title": "GIVE: cuidar el vínculo", "content": "Mientras pedís, GIVE te ayuda a que tu pareja no se sienta atacada:\n\n- **G: Gentileza.** Sin insultos, amenazas, ironías ni «siempre/nunca».\n- **I: Interés.** Escuchá su punto de vista sin interrumpir, aunque no estés de acuerdo.\n- **V: Validar.** Mostrá que entendés lo que siente o piensa.\n- **E: Estilo tranquilo.** Un tono relajado, una sonrisa, algo de humor si encaja.\n\nElegir un buen momento también cuenta: no en medio de una pelea, ni con apuro, ni cuando alguno está muy cansado." }, { "id": "give_elegidos", "type": "checklist", "prompt": "¿Qué te cuesta más y querés cuidar especialmente en esta charla?", "options": [ "No subir el tono", "No usar «siempre» o «nunca»", "Escuchar sin interrumpir", "No traer temas viejos", "Mostrar que entiendo lo que siente", "Volver a mi pedido si nos desviamos", "Elegir un buen momento" ], "min": 1, "max": 3 }, { "id": "validacion_info", "type": "info", "title": "Validar en tres niveles", "content": "**Validar no es darle la razón.** Es mostrar que entendés que lo que siente tiene sentido desde su lugar. Tres niveles simples:\n\n- **1. Prestar atención.** Mirarlo, dejar el celular, asentir. Que note que lo escuchás.\n- **2. Reflejar.** Decir con tus palabras lo que entendiste: «O sea que llegás muy cansado y no tenés ganas de hablar».\n- **3. Darle sentido.** Mostrar que su reacción es comprensible: «Tiene sentido que te moleste, con el día que tuviste».\n\nMuchas veces, cuando el otro se siente entendido, **baja la defensa** y es más fácil que escuche tu pedido." }, { "id": "validacion", "type": "text", "prompt": "¿Qué podría sentir tu pareja al escucharte? Escribí una frase para validarla.", "placeholder": "Entiendo que…" }, { "id": "cierre", "type": "reflect", "title": "Tu guion para la conversación", "template": "«{{describir}}. {{expresar}}. {{afirmar}}. {{reforzar}}.» Si no se puede así: {{negociar}}. Mientras hablamos voy a cuidar: {{give_elegidos}}. Para validar puedo decir: «{{validacion}}».", "content": "No hace falta repetir el guion de memoria: es una guía. Si la conversación no sale como esperabas, **no es un fracaso**: podés retomarla otro día o traerla a sesión para revisarla." } ]$steps$::jsonb),
  ('cuadro-pareja-tcc-pensamientos', 'Lo que pienso cuando discutimos', 'Detectá pensamientos automáticos en la pareja (lectura de mente, personalización, siempre/nunca), buscá otra mirada y armá un pedido concreto.', 'custom', 'tcc', 'todos', 'cuadros', 12, 353,
   $steps$[ { "id": "intro", "type": "info", "title": "La pelea que pasa en la cabeza", "content": "En una discusión de pareja, muchas veces no reaccionamos solo a lo que el otro hizo, sino a **lo que pensamos que significa**.\n\nLlega tarde sin avisar y en un segundo la mente dice: «no le importo». Ese pensamiento automático trae enojo o tristeza, y con eso respondemos. El otro se defiende, y la pelea crece.\n\nRevisar esos pensamientos **no es darle la razón al otro ni restarle importancia a lo que te pasa**. Es separar lo que pasó de la historia que se armó encima, para poder pedir lo que necesitás con más claridad." }, { "id": "trampas", "type": "info", "title": "Tres trampas frecuentes en pareja", "content": "- **Lectura de mente:** suponer que sabés lo que el otro piensa o siente. «Está serio, seguro está harto de mí». «Si me quisiera, sabría lo que necesito».\n- **Personalización:** tomar como dirigido a vos algo que puede tener otras causas. «Llegó de mal humor: algo hice».\n- **Siempre y nunca:** convertir una situación en una regla. «Nunca me escuchás». «Siempre hacés lo mismo».\n\nLas tres son muy humanas. El problema es que **se sienten como hechos**, y discutir desde ahí hace que el otro se defienda en lugar de escuchar." }, { "id": "quiz", "type": "choice", "prompt": "«No me contestó en dos horas: ya no le importo». ¿Qué trampa aparece más acá?", "options": [ "Lectura de mente", "Personalización", "Siempre y nunca" ], "feedback": { "Lectura de mente": "**Sí.** Se da por sentado lo que el otro siente («no le importo») sin datos: podría estar ocupado, sin batería o distraído.", "Personalización": "**Tiene algo de eso**, porque se toma la demora como algo sobre vos. Pero la trampa principal es la **lectura de mente**: suponer lo que el otro siente sin preguntarle.", "Siempre y nunca": "**Acá no aparece un «siempre» o «nunca».** La trampa principal es la **lectura de mente**: suponer que no le importás sin datos que lo confirmen." } }, { "id": "seguridad", "type": "info", "title": "Antes de seguir", "content": "Este recurso es para conflictos comunes entre dos personas que pueden hablar sin miedo. **Si en tu relación hay violencia**, amenazas o control, o sentís miedo de tu pareja, lo que pasa no es una trampa de tu pensamiento: **la prioridad es tu seguridad**.\n\nSi estás en riesgo o en crisis, pedí ayuda ya: a emergencias, a una línea de ayuda o en la guardia del hospital más cercano. En la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos. Y hablalo con tu psicólogo." }, { "id": "situacion", "type": "text", "prompt": "Pensá en un conflicto reciente. ¿Qué pasó? Contalo como lo vería una cámara, sin interpretaciones.", "placeholder": "El sábado llegó dos horas tarde y no avisó…" }, { "id": "pensamiento", "type": "text", "prompt": "¿Qué pensaste en ese momento sobre tu pareja, sobre vos o sobre la relación?", "placeholder": "Pensé que…" }, { "id": "malestar_antes", "type": "scale", "prompt": "Al recordar ese pensamiento ahora, ¿qué tan fuerte es el malestar?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Muchísimo", "maps_to": "emotion_before" }, { "id": "trampas_mias", "type": "checklist", "prompt": "¿En qué trampas pudiste haber caído?", "options": [ "Lectura de mente", "Personalización", "Siempre y nunca", "Pensar en lo peor que puede pasar", "Ponerle una etiqueta al otro («es un egoísta»)", "No estoy seguro o segura" ], "min": 1 }, { "id": "preguntas", "type": "info", "title": "Buscar otra mirada", "content": "Algunas preguntas para revisar el pensamiento:\n\n- ¿Qué **datos** tengo de que esto es así? ¿Se lo pregunté?\n- ¿Qué **otras explicaciones** podría haber?\n- ¿Es **siempre**, o fue esta vez (o algunas veces)?\n- Si una amiga o un amigo me contara esto, **¿qué le diría?**\n\nEl pensamiento alternativo no tiene que negar lo que te dolió. Puede ser algo como: «Me dolió que no avisara. No sé por qué fue; puedo preguntarle y decirle qué necesito»." }, { "id": "alternativo", "type": "text", "prompt": "Escribí un pensamiento alternativo, más completo y justo con los dos.", "placeholder": "Me molestó que… y a la vez…" }, { "id": "pedido", "type": "text", "prompt": "Convertí la queja en un pedido concreto. Ej.: «¿Me avisás con un mensaje si vas a llegar tarde?».", "placeholder": "¿Podrías…?" }, { "id": "malestar_despues", "type": "scale", "prompt": "Después de revisarlo, ¿qué tan fuerte es ahora el malestar?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Muchísimo", "maps_to": "emotion_after" }, { "id": "cierre", "type": "reflect", "title": "Tu registro del conflicto", "template": "Lo que pasó: {{situacion}}. Lo que pensé: «{{pensamiento}}» (trampas: {{trampas_mias}}). Otra forma de verlo: «{{alternativo}}». Mi pedido concreto: «{{pedido}}».", "content": "Un pedido concreto le da al otro algo que **puede hacer**, en lugar de algo de lo que defenderse. Si el malestar no bajó, está bien: algunas heridas necesitan más que un ejercicio. Traé este registro a tu próxima sesión." } ]$steps$::jsonb),
  ('cuadro-regulacion-dbt-hechos', 'Verificar los hechos y resolver', 'Revisá si tu emoción y su intensidad encajan con los hechos (DBT) y decidí si conviene resolver el problema o probar la acción opuesta.', 'custom', 'dbt', 'todos', 'cuadros', 13, 354,
   $steps$[ { "id": "intro", "type": "info", "title": "¿La emoción encaja con lo que pasó?", "content": "Las emociones tienen una función: el miedo nos protege de un peligro, el enojo nos ayuda a defender algo importante, la tristeza nos avisa de una pérdida.\n\nPero a veces la emoción no responde tanto a **lo que pasó** como a **lo que interpretamos** de lo que pasó. Y otras veces la emoción encaja, pero llega con una intensidad mucho mayor.\n\nEn DBT, **verificar los hechos** es frenar un momento y preguntarte: ¿mi emoción, y su intensidad, encajan con los hechos? La respuesta te ayuda a elegir qué hacer después." }, { "id": "seguridad", "type": "info", "title": "Antes de empezar", "content": "Si mientras hacés este recurso aparecen pensamientos de hacerte daño, de que no valés la pena vivir, o sentís que estás en crisis, **dejá el ejercicio para otro momento y pedí ayuda ya**: a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos.\n\nNo tenés que atravesarlo solo ni sola. Contáselo también a tu psicólogo." }, { "id": "emocion", "type": "text", "prompt": "¿Qué emoción querés revisar? Nombrala y contá en una frase qué la disparó.", "placeholder": "Enojo, porque…" }, { "id": "intensidad_antes", "type": "scale", "prompt": "¿Qué tan intensa es esa emoción ahora?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Al máximo", "maps_to": "emotion_before" }, { "id": "pasos_info", "type": "info", "title": "Cómo verificar los hechos", "content": "Hacete estas preguntas, de a una:\n\n- **¿Qué pasó exactamente?** Solo lo que vería una cámara.\n- **¿Qué interpretaciones le sumé?** Lo que supuse sobre las intenciones del otro o sobre lo que va a pasar.\n- **¿Estoy viendo una amenaza?** ¿Cuál? ¿Qué tan probable es que ocurra de verdad?\n- **Si ocurriera lo peor, ¿cómo podría afrontarlo?**\n- **¿La emoción y su intensidad encajan con los hechos**, no con la interpretación?\n\nNo buscás «tener razón» ni convencerte de que no te pasa nada: buscás **ver con más claridad**." }, { "id": "hechos", "type": "text", "prompt": "¿Qué pasó? Escribí solo los hechos, sin interpretaciones.", "placeholder": "Mi jefa me pidió que rehaga el informe…" }, { "id": "interpretaciones", "type": "text", "prompt": "¿Qué interpretaciones o suposiciones le sumaste a esos hechos?", "placeholder": "Pensé que…" }, { "id": "encaja", "type": "choice", "prompt": "Mirando solo los hechos, ¿tu emoción y su intensidad encajan?", "options": [ "Sí, encajan con lo que pasó", "La emoción encaja, pero no tanta intensidad", "No encaja: responde más a mi interpretación" ], "feedback": { "Sí, encajan con lo que pasó": "**Entonces tu emoción te está dando información válida.** Si hay un problema que se puede cambiar, el camino suele ser **resolverlo**. Si no se puede cambiar, toca tolerar y cuidarte mientras pasa.", "La emoción encaja, pero no tanta intensidad": "**Es muy frecuente.** Podés reconocer que algo te afectó y, a la vez, bajar la intensidad: con habilidades del cuerpo, con acción opuesta parcial y resolviendo la parte del problema que sí depende de vos.", "No encaja: responde más a mi interpretación": "**Bien visto.** Cuando la emoción no encaja con los hechos, una opción útil es la **acción opuesta**: hacer lo contrario de lo que la emoción te empuja a hacer." } }, { "id": "cuando_info", "type": "info", "title": "¿Resolver o acción opuesta?", "content": "- **La emoción encaja y el problema se puede cambiar:** usá **resolución de problemas**.\n- **La emoción no encaja con los hechos**, o encaja pero actuar según ella te perjudica (por ejemplo, gritar te hace perder algo que te importa): probá la **acción opuesta**. Si el miedo no encaja, acercarte; si el enojo no encaja, alejarte con amabilidad.\n- **La emoción encaja y el problema no se puede cambiar:** el trabajo es tolerar y aceptar, cuidándote mientras dura.\n\nLa acción opuesta la tenés explicada en la práctica de habilidades para emociones intensas de esta sección." }, { "id": "resolver_info", "type": "info", "title": "Resolución de problemas, paso a paso", "content": "1. **Definí el problema** con hechos, en una frase.\n2. **Elegí un objetivo realista**: qué tendría que pasar para que esté un poco mejor.\n3. **Pensá varias soluciones** sin juzgarlas todavía. Cuantas más, mejor.\n4. **Elegí una o dos** que tengan más chances de funcionar y que puedas hacer.\n5. **Dividila en pasos** chicos y empezá por el primero.\n6. **Evaluá cómo salió.** Si no funcionó, volvé al paso 3: no es un fracaso, es información." }, { "id": "soluciones", "type": "list", "prompt": "Si hay un problema para resolver, anotá posibles soluciones sin juzgarlas todavía.", "count": 4, "min": 1, "optional": true }, { "id": "plan", "type": "text", "prompt": "¿Qué vas a hacer ahora? Escribí el primer paso concreto, sea resolver o acción opuesta.", "placeholder": "Voy a…" }, { "id": "intensidad_despues", "type": "scale", "prompt": "Después de revisar los hechos, ¿qué tan intensa es la emoción ahora?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Al máximo", "maps_to": "emotion_after" }, { "id": "cierre", "type": "reflect", "title": "Lo que verificaste", "template": "Emoción: {{emocion}}. Los hechos: {{hechos}}. Lo que le sumé: {{interpretaciones}}. ¿Encaja? {{encaja}}. Posibles soluciones: {{soluciones}}. Mi primer paso: {{plan}}.", "content": "Verificar los hechos no borra la emoción, y no tiene por qué. Te ayuda a **elegir qué hacer con ella** en lugar de que ella elija por vos. Con práctica, este chequeo se vuelve más rápido." } ]$steps$::jsonb),
  ('cuadro-regulacion-act-espacio', 'Hacerle espacio a lo que siento', 'Practicá la expansión de ACT: observar, respirar hacia la sensación, permitir y nombrar una emoción difícil, y elegir una acción valiosa.', 'custom', 'act', 'todos', 'cuadros', 11, 355,
   $steps$[ { "id": "intro", "type": "info", "title": "Cuando pelear la agranda", "content": "Ante una emoción difícil, lo natural es querer sacársela de encima: distraerse, taparla, discutirla, aguantar apretando los dientes. A veces funciona un rato. Pero muchas veces, **cuanto más peleamos con una emoción, más espacio ocupa**.\n\nEn ACT se propone otra opción: la **expansión**, o hacerle espacio. No es resignarse ni que te tenga que gustar lo que sentís. Es dejar de forcejear, para que la emoción pueda estar **sin manejar tu vida**.\n\nLleva práctica, y al principio puede sentirse raro. Está bien." }, { "id": "seguridad", "type": "info", "title": "Antes de empezar", "content": "Si mientras hacés este recurso aparecen pensamientos de hacerte daño, de que no valés la pena vivir, o sentís que estás en crisis, **dejá el ejercicio para otro momento y pedí ayuda ya**: a emergencias, a una línea de ayuda o en la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos.\n\nNo tenés que atravesarlo solo ni sola. Contáselo también a tu psicólogo." }, { "id": "emocion", "type": "text", "prompt": "¿Qué emoción difícil está presente ahora, o aparece seguido? Nombrala.", "placeholder": "Angustia, miedo, bronca…" }, { "id": "intensidad_antes", "type": "scale", "prompt": "¿Qué tan intensa la sentís en este momento?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Al máximo", "maps_to": "emotion_before" }, { "id": "cuerpo", "type": "checklist", "prompt": "¿Dónde la notás en el cuerpo?", "options": [ "Pecho", "Garganta", "Estómago o panza", "Hombros o cuello", "Cara o mandíbula", "Manos", "Cabeza", "No la ubico en un lugar" ], "min": 1 }, { "id": "pasos_info", "type": "info", "title": "Cuatro movimientos", "content": "- **Observar.** Notá la sensación con curiosidad, como si fuera la primera vez: ¿dónde empieza y termina?, ¿es pesada, caliente, apretada?, ¿se mueve?\n- **Respirar hacia la sensación.** Imaginá que el aire llega hasta ese lugar y la rodea.\n- **Permitir.** No hace falta que te guste. Solo dejá de empujarla: «no me gusta, y puedo dejarla estar».\n- **Nombrar.** Ponele nombre: «esto es angustia», «acá hay miedo». Nombrar ayuda a mirarla un poco desde afuera.\n\nSi en algún momento sentís que te desbordás, abrí los ojos, apoyá los pies y mirá a tu alrededor. Podés parar cuando quieras." }, { "id": "practica", "type": "timed_info", "title": "Práctica guiada", "seconds": 150, "content": "Apoyá los pies en el piso y soltá un poco los hombros.\n\nLlevá la atención al lugar del cuerpo donde está la emoción. **Observala**: su tamaño, su forma, su temperatura.\n\nAhora **respirá hacia ella**. Con cada inhalación, imaginá que el aire la rodea y le hace un poco más de lugar.\n\n**Permitila.** Si aparece el impulso de pelearla, notalo y volvé a aflojar. Podés decirte: «hay lugar para esto».\n\n**Nombrala** en silencio: «esto es…».\n\nSi la mente se va, está bien: volvé con suavidad a la sensación. Seguí respirando hasta que suene el aviso." }, { "id": "que_paso", "type": "checklist", "prompt": "¿Qué notaste durante la práctica?", "options": [ "La sensación cambió de forma o de lugar", "Bajó un poco", "Subió al principio", "Me costó quedarme con ella", "Sentí más espacio alrededor", "Tuve ganas de distraerme", "No noté cambios" ], "min": 1 }, { "id": "intensidad_despues", "type": "scale", "prompt": "Y ahora, ¿qué tan intensa la sentís?", "min": 0, "max": 10, "min_label": "Nada", "max_label": "Al máximo", "maps_to": "emotion_after" }, { "id": "valores_info", "type": "info", "title": "Y ahora, ¿hacia dónde?", "content": "El objetivo de hacer espacio **no es que la emoción desaparezca** (a veces baja, a veces no). Es que deje de decidir por vos.\n\nLa energía que se iba en pelear con lo que sentís queda disponible para **lo que te importa**: una persona, un proyecto, cuidarte, aprender algo.\n\nLa emoción puede venir con vos mientras hacés eso. Como un pasajero incómodo: está en el auto, pero el volante lo tenés vos." }, { "id": "accion", "type": "text", "prompt": "Si esta emoción pudiera acompañarte, ¿qué harías hoy que vaya con lo que te importa?", "placeholder": "Hoy voy a…" }, { "id": "frase", "type": "text", "prompt": "¿Qué frase corta te puede recordar hacer espacio? Ej.: «Hay lugar para esto».", "placeholder": "Hay lugar para…" }, { "id": "cierre", "type": "reflect", "title": "Tu práctica", "template": "Hoy le hice espacio a: {{emocion}}. La noté en: {{cuerpo}}. Durante la práctica: {{que_paso}}. Con ella a bordo, voy a {{accion}}. Mi frase: «{{frase}}».", "content": "Hacer espacio es una habilidad que se entrena: cuanto más la practiques en momentos de malestar moderado, más disponible la vas a tener cuando la emoción sea fuerte. Contá en sesión cómo te fue." } ]$steps$::jsonb),
  ('cuadro-adolescentes-tcc-ansiedad', 'Ansiedad en la escuela y los exámenes', 'Para adolescentes: qué pensamientos aparecen antes de una prueba, cómo estudiar por partes, respirar antes de rendir y a quién pedir ayuda.', 'custom', 'tcc', 'todos', 'cuadros', 13, 356,
   $steps$[ { "id": "intro", "type": "info", "title": "Nervios antes de rendir", "content": "Ponerte nervioso o nerviosa antes de una prueba es **normal**. Un poco de nervios hasta ayuda: te mantiene despierto y concentrado.\n\nEl problema es cuando los nervios se vuelven tanto que **no te dejan estudiar, dormir o pensar** en el momento de la prueba.\n\nSuele pasar algo así: aparece un pensamiento («me va a ir horrible») → el cuerpo se acelera → dan ganas de evitar (no estudiar, faltar, dejar para después) → al evitar, la prueba se ve más difícil y los nervios suben más.\n\nAcá vas a ver cómo cortar ese círculo en tres partes: **lo que pensás, cómo estudiás y qué hacés con el cuerpo**." }, { "id": "seguridad", "type": "info", "title": "Antes de seguir", "content": "Si en algún momento sentís que no podés más, tenés ganas de hacerte daño o pensás que sería mejor no estar, **no te lo guardes: pedí ayuda ya**.\n\n- Contáselo a un **adulto de confianza**: tu mamá, tu papá, otro familiar, un profe, el psicólogo de la escuela.\n- Si es urgente, llamá a emergencias, a una línea de ayuda o andá a la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos. Pedir ayuda no es exagerar: es cuidarte." }, { "id": "senales", "type": "checklist", "prompt": "¿Qué te pasa cuando se acerca una prueba? Marcá lo que te suene.", "options": [ "Dolor de panza o de cabeza", "Me cuesta dormir", "Me quedo en blanco", "Dejo estudiar para último momento", "Tengo ganas de faltar", "Siento el corazón rápido", "Pienso que me va a ir mal", "Estoy más irritable" ], "min": 1 }, { "id": "pensamientos_info", "type": "info", "title": "Lo que te dice la cabeza", "content": "Antes de una prueba es común que aparezcan pensamientos como:\n\n- «Me voy a sacar un 1».\n- «Me voy a quedar en blanco».\n- «Todos entienden menos yo».\n- «Si me va mal, soy un fracaso».\n\nSon **predicciones**, no hechos. Tu cabeza intenta protegerte imaginando lo peor, pero se pasa de rosca.\n\nPreguntas que ayudan:\n\n- ¿Qué pasó **de verdad** en otras pruebas?\n- Si me va mal, ¿qué podría hacer? (recuperatorio, pedir ayuda, aprender para la próxima)\n- Una nota habla de una prueba, **no de quién soy**." }, { "id": "pensamiento", "type": "text", "prompt": "¿Qué pensamiento te aparece más antes de una prueba?", "placeholder": "Me voy a…" }, { "id": "amigo", "type": "text", "prompt": "Si tu mejor amigo o amiga tuviera ese pensamiento, ¿qué le dirías?", "placeholder": "Le diría que…" }, { "id": "estudio_info", "type": "info", "title": "Estudiar por partes", "content": "Un tema entero puede parecer una montaña. **Dividido en partes, se vuelve una escalera.**\n\n- **Dividí** el tema en partes chicas (un capítulo, un tipo de ejercicio, una unidad).\n- **Repartilas** en los días que faltan, dejando el último día para repasar.\n- **Estudiá en bloques** de unos 25 minutos con 5 de descanso. Celular lejos durante el bloque.\n- **Arrancá por algo fácil** para entrar en ritmo.\n- **Practicá** como si fuera la prueba: hacé ejercicios, explicá en voz alta, armá preguntas.\n- **Dormí.** Quedarte despierto toda la noche suele empeorar la memoria y los nervios." }, { "id": "prueba", "type": "text", "prompt": "¿Qué prueba o entrega tenés cerca? Anotá de qué materia es y cuándo.", "placeholder": "Matemática, el viernes" }, { "id": "partes", "type": "list", "prompt": "Dividí lo que tenés que estudiar en partes chicas. Una por línea.", "count": 5, "min": 2 }, { "id": "respiracion", "type": "timed_info", "title": "Respirar antes de la prueba", "seconds": 90, "content": "Esto lo podés hacer en el banco, antes de que repartan las hojas, sin que nadie lo note.\n\nApoyá bien los dos pies en el piso. Sentí el contacto.\n\nTomá aire por la nariz **contando hasta 4**.\n\nSoltalo despacio por la boca **contando hasta 6**, como si apagaras una vela de a poco.\n\nRepetilo. Si te perdés en la cuenta, no pasa nada: volvé a empezar.\n\nSi te quedás en blanco durante la prueba, hacé tres respiraciones así, leé otra pregunta que te resulte más fácil y después volvé." }, { "id": "adultos", "type": "checklist", "prompt": "¿A qué adulto de confianza le podrías contar cómo te sentís con las pruebas?", "help": "Contarlo no es quejarse ni ser débil. Un adulto puede ayudarte a organizarte, hablar con la escuela o acompañarte si los nervios son muchos.", "options": [ "Mi mamá o mi papá", "Otro familiar", "Un profe o tutor", "El psicólogo o psicóloga de la escuela", "Mi psicólogo o psicóloga", "Otro adulto" ], "min": 1 }, { "id": "primer_paso", "type": "text", "prompt": "¿Cuál es tu primer paso para hoy o mañana?", "placeholder": "Hoy voy a estudiar la primera parte 25 minutos…" }, { "id": "cierre", "type": "reflect", "title": "Tu plan para la prueba", "template": "Prueba: {{prueba}}. Cuando mi cabeza diga «{{pensamiento}}», me voy a acordar de lo que le diría a un amigo: «{{amigo}}». Voy a estudiar por partes: {{partes}}. Mi primer paso: {{primer_paso}}. Si los nervios son muchos, se lo cuento a: {{adultos}}.", "content": "Antes de rendir, acordate de la respiración 4 y 6. Y si la ansiedad no te deja dormir, comer o ir a la escuela, **contáselo a un adulto**: hay ayuda para esto." } ]$steps$::jsonb),
  ('cuadro-adolescentes-dbt-habilidades', 'Habilidades para cuando la emoción explota', 'Para adolescentes: tu sabio o sabia interior, TIPP con cuidados, caminos del medio y validarte, más un plan para la próxima vez.', 'custom', 'dbt', 'todos', 'cuadros', 14, 357,
   $steps$[ { "id": "intro", "type": "info", "title": "Tres formas de estar", "content": "En DBT se habla de tres «mentes», o formas de estar:\n\n- **Mente emocional:** la emoción manda. Todo es urgente y hacés lo primero que te sale.\n- **Mente racional:** solo lógica, como si no sintieras nada.\n- **Mente sabia:** tu **sabio o sabia interior**. Escucha lo que sentís *y* lo que pensás, y elige qué te conviene de verdad.\n\nTodas las personas tienen una parte sabia, aunque a veces quede tapada por la emoción. Las habilidades de este recurso te ayudan a encontrarla." }, { "id": "seguridad", "type": "info", "title": "Antes de seguir", "content": "Si en algún momento sentís que no podés más, tenés ganas de hacerte daño o pensás que sería mejor no estar, **no te lo guardes: pedí ayuda ya**.\n\n- Contáselo a un **adulto de confianza**: tu mamá, tu papá, otro familiar, un profe, el psicólogo de la escuela.\n- Si es urgente, llamá a emergencias, a una línea de ayuda o andá a la guardia del hospital más cercano.\n\nEn la app, la sección **Calmarme** tiene el recuadro «Si necesitás ayuda urgente» con los teléfonos. Pedir ayuda no es exagerar: es cuidarte." }, { "id": "quiz_mente", "type": "choice", "prompt": "Te dejaron en visto y querés mandar diez mensajes enojado o enojada. ¿Qué mente está al mando?", "options": [ "Mente emocional", "Mente racional", "Mente sabia" ], "feedback": { "Mente emocional": "**Sí.** Cuando la emoción manda, todo parece urgente. La mente sabia podría decir: «Estoy enojado; espero diez minutos y después decido qué escribir».", "Mente racional": "**No tanto:** la racional sería pensar «es solo un mensaje» sin registrar lo que sentís. Acá la que manda es la **emocional**.", "Mente sabia": "**Todavía no:** la sabia escucharía el enojo sin dejar que decida por vos. Mandar diez mensajes es la **mente emocional** al mando." } }, { "id": "sabio", "type": "timed_info", "title": "Encontrar a tu sabio o sabia interior", "seconds": 60, "content": "Sentate cómodo o cómoda y respirá despacio.\n\nCon cada inhalación, decite por dentro «sabia» (o «sabio»). Con cada exhalación, «mente».\n\nImaginá que bajás despacio a un lugar tranquilo dentro tuyo, como una piedra que se hunde en un lago calmo.\n\nDesde ahí, preguntate: **¿qué necesito de verdad ahora?** No hace falta que la respuesta llegue enseguida. Solo escuchá." }, { "id": "tipp", "type": "info", "title": "TIPP: cuando estás en 9 o 10", "content": "Cuando la emoción está altísima, primero hay que **bajar el cuerpo**:\n\n- **T, temperatura:** agua fría en la cara unos 30 segundos, o una bolsa fría en los ojos y las mejillas.\n- **I, ejercicio intenso:** unos minutos de saltar, correr o subir escaleras.\n- **P, respiración pausada:** soltar el aire más lento de lo que lo tomás.\n- **P, relajación muscular:** apretar un músculo unos segundos y soltarlo.\n\n**Cuidados importantes:** el agua fría baja el ritmo del corazón. Si tenés algún problema del corazón, presión baja, desmayos, asma, un trastorno de la alimentación u otra condición médica, **no uses agua fría ni ejercicio intenso sin consultarlo antes** con un adulto y tu médico. No te metas entero en agua helada. No te pases con el ejercicio." }, { "id": "caminos_info", "type": "info", "title": "Caminos del medio", "content": "Cuando la emoción sube, la cabeza piensa en **todo o nada**:\n\n- «O estudio cinco horas, o no estudio nada».\n- «O me quiere, o me odia».\n- «Si me equivoqué en una cosa, arruiné todo».\n\nCasi siempre hay un **camino del medio**: estudiar 30 minutos; «estamos peleados y igual me quiere»; «me salió mal esto y otras cosas me salen bien».\n\nUna clave: cambiar el **«pero»** por el **«y»**. «Estoy enojado con mi mamá **y** la quiero». Las dos cosas pueden ser verdad al mismo tiempo." }, { "id": "todo_nada", "type": "text", "prompt": "Escribí un pensamiento de «todo o nada» que te aparezca seguido.", "placeholder": "O… o…" }, { "id": "medio", "type": "text", "prompt": "Ahora escribí una versión del medio, más flexible.", "placeholder": "…y también…" }, { "id": "validar_info", "type": "info", "title": "Validarte a vos", "content": "**Validarte es decirte que lo que sentís tiene sentido**, sin retarte por sentirlo.\n\nNo significa que todo lo que hagas esté bien. Significa reconocer: «Con lo que pasó, tiene sentido que esté triste». A partir de ahí es más fácil elegir qué hacer.\n\nLo contrario sería decirte «sos un exagerado», «no deberías sentirte así», «qué tonta que sos». Eso suele hacer que la emoción **suba**, no que baje.\n\nProbá hablarte como le hablarías a alguien que querés y que la está pasando mal." }, { "id": "validacion", "type": "text", "prompt": "Escribí una frase para validarte la próxima vez que algo te duela.", "placeholder": "Tiene sentido que me sienta así porque…" }, { "id": "senales", "type": "text", "prompt": "Tu plan: ¿qué señales te avisan que la emoción está empezando a subir?", "placeholder": "Se me cierra la garganta, aprieto los puños…" }, { "id": "habilidad", "type": "choice", "prompt": "Cuando notes esas señales, ¿qué vas a probar primero?", "options": [ "Buscar a mi sabio o sabia interior", "Una parte del TIPP", "Buscar un camino del medio", "Validarme", "Hablar con alguien de confianza" ] }, { "id": "adulto", "type": "text", "prompt": "¿A qué adulto de confianza le podés pedir ayuda si la emoción no baja?", "placeholder": "Mi tía, mi profe de…" }, { "id": "cierre", "type": "reflect", "title": "Tu plan para la próxima vez", "template": "Cuando note que {{senales}}, primero voy a: {{habilidad}}. Me voy a decir: «{{validacion}}». Si pienso «{{todo_nada}}», busco el camino del medio: «{{medio}}». Si la emoción no baja, le pido ayuda a: {{adulto}}.", "content": "Las habilidades se aprenden practicando, sobre todo cuando la emoción está en 4 o 5, no solo en 10. Si un día no te salen, **no pasa nada**: es parte de aprender. Y pedir ayuda a un adulto también es una habilidad." } ]$steps$::jsonb)
on conflict (slug) do nothing;

-- Recursos de la biblioteca de Materiales (abren el ejercicio correspondiente).
insert into public.materials (title, description, type, category_id, exercise_template_id, duration_minutes, visibility, is_published)
select v.title, v.description, 'exercise', c.id, t.id, t.estimated_minutes, 'assigned', true
from (values
  ('cuadro-panico-act-aceptacion', 'Pánico: dejar de pelear con las sensaciones (ACT)', 'Disposición frente a las sensaciones del pánico, defusión del pensamiento «me va a pasar algo», metáfora del tira y afloje y práctica de observación de 2 minutos.', 'ansiedad'),
  ('cuadro-panico-dbt-crisis', 'Mi kit para un pico de ansiedad (DBT)', 'Habilidades de supervivencia a la crisis para picos de ansiedad: STOP, respiración pausada, autocalmarse con los cinco sentidos, distracción ACCEPTS y kit personal.', 'ansiedad'),
  ('cuadro-depresion-act-valores', 'Mis valores y un paso chico (ACT)', 'Valores por área de vida, diana de valores, una acción comprometida chica para la semana y plan para las barreras, para el ánimo bajo.', 'depresion'),
  ('cuadro-depresion-dbt-positivos', 'Sumar momentos buenos y cuidar el cuerpo (DBT)', 'Acumular emociones positivas a corto y largo plazo y habilidades PLEASE (salud, alimentación, sustancias, sueño, ejercicio), con plan semanal.', 'depresion'),
  ('cuadro-toc-act-defusion', 'TOC: tomar distancia de las obsesiones (ACT)', 'Defusión para obsesiones: «estoy teniendo el pensamiento de…», nombrar la historia y hojas en el río, sin rituales mentales ni búsqueda de certeza.', 'toc'),
  ('cuadro-toc-tcc-responsabilidad', 'TOC: revisar la amenaza y la responsabilidad (TCC)', 'Reevaluación de la sobreestimación de la amenaza, la responsabilidad inflada (torta de responsabilidad) y la fusión pensamiento-acción. La EPR se planifica en sesión.', 'toc'),
  ('cuadro-trauma-dbt-tolerancia', 'Atravesar momentos de mucha activación (DBT)', 'Tolerancia al malestar para la activación postraumática: TIPP con precauciones médicas, autocalmarse con los sentidos y aceptación radical (aceptar no es aprobar).', 'trauma'),
  ('cuadro-trauma-act-autocompasion', 'Tratarme con amabilidad frente a la culpa (ACT)', 'Yo observador (el cielo y el clima) y autocompasión frente a la culpa y la vergüenza: mano en el pecho, frases amables y carta de un amigo compasivo, sin relatar el hecho.', 'trauma'),
  ('cuadro-duelo-act-valores', 'Llevar a quien perdí en lo que hago (ACT)', 'Hacerle lugar al dolor del duelo y honrar a quien se perdió desde los valores: lo que te enseñó, cómo llevarlo en tus acciones, dolor y amor como dos caras.', 'duelo'),
  ('cuadro-duelo-tcc-culpa', 'Duelo: cuando aparecen la culpa y los «hubiera» (TCC)', 'Revisión cuidadosa de pensamientos de culpa en el duelo: sesgo retrospectivo (lo que sabías entonces vs. ahora), otros factores y doble estándar.', 'duelo'),
  ('cuadro-burnout-act-valores', 'Burnout: volver a lo que te importa (ACT)', 'Ejercicio de ACT para el estrés laboral: valores y metas, reconectar con lo que importa dentro y fuera del trabajo, acción comprometida y un «no» alineado.', 'estres'),
  ('cuadro-burnout-dbt-limites', 'Burnout: poner límites con DEAR MAN y FAST (DBT)', 'Ejercicio de DBT para el estrés laboral: armar el guion de una conversación real para poner un límite o pedir un cambio, cuidando el autorrespeto.', 'estres'),
  ('cuadro-sueno-tcc-pensamientos', 'Sueño: los pensamientos que desvelan (TCC)', 'Ejercicio de TCC para el insomnio: identificar y revisar pensamientos catastróficos sobre el sueño y programar un tiempo de preocupación lejos de la cama.', 'sueno'),
  ('cuadro-sueno-relajacion', 'Sueño: relajación muscular progresiva y escaneo corporal', 'Práctica guiada por grupos musculares y escaneo corporal breve para bajar la activación antes de acostarse, sin presión por dormir.', 'sueno'),
  ('cuadro-fobias-tcc-experimentos', 'Ansiedad social: experimentos conductuales (TCC)', 'Ejercicio de TCC para ansiedad social: predicción, conductas de seguridad a soltar, qué pasó realmente y conclusión, para acordar con el psicólogo.', 'ansiedad'),
  ('cuadro-fobias-act-disposicion', 'Miedo y disposición: el pasajero en el colectivo (ACT)', 'Ejercicio de ACT para fobias y ansiedad social: disposición a sentir miedo al servicio de valores, metáfora del colectivo y un paso valioso.', 'ansiedad'),
  ('cuadro-tdah-dbt-emociones', 'TDAH: regulación emocional con DBT', 'Ejercicio de DBT para la frustración rápida y la sensibilidad al rechazo en TDAH: STOP, verificar los hechos y acción opuesta.', 'tdah'),
  ('cuadro-tdah-tcc-postergacion', 'TDAH: salir de la postergación (TCC)', 'Ejercicio de TCC para la procrastinación en TDAH: pensamientos que la sostienen, regla de los 5 minutos, primer paso concreto y recompensas.', 'tdah'),
  ('cuadro-alimentacion-dbt-impulsos', 'Comida: surfear el impulso (DBT)', 'Ejercicio de DBT para impulsos de atracón o de compensar: surfear la ola, distracción, autocalmarse y qué hacer después, dentro de un tratamiento en equipo.', 'alimentacion'),
  ('cuadro-alimentacion-tcc-imagen', 'Imagen corporal: chequeo, evitación y comparaciones (TCC)', 'Ejercicio de TCC sobre imagen corporal: chequeo y evitación del cuerpo, comparaciones, redes sociales y apreciación funcional del cuerpo.', 'alimentacion'),
  ('cuadro-autoestima-tcc-creencias', 'Revisar una creencia de fondo (TCC)', 'Registro de evidencias a favor y en contra de una creencia nuclear durante una semana, con creencia alternativa y porcentajes de credibilidad.', 'autoestima'),
  ('cuadro-autoestima-act-yo', 'El yo como contexto (ACT)', 'Metáfora del cielo y el clima, práctica guiada del observador de 2 minutos y una acción valiosa a pesar de la voz crítica.', 'autoestima'),
  ('cuadro-pareja-dbt-pedir', 'Pedir y cuidar el vínculo en pareja (DBT)', 'DEAR MAN para pedir algo concreto a la pareja, GIVE para cuidar la relación y validación en tres niveles, con aviso de seguridad.', 'relaciones'),
  ('cuadro-pareja-tcc-pensamientos', 'Pensamientos automáticos en la pareja (TCC)', 'Lectura de mente, personalización y «siempre/nunca» en la pareja: registro de un conflicto, pensamiento alternativo y pedido concreto.', 'relaciones'),
